#!/usr/bin/env node
// Runs one Codex turn through `codex app-server` (JSON-RPC over stdio) at a declared rights level.
//
// Why app-server rather than `codex exec`: exec forces approval_policy=Never internally. Where an MDM
// profile restricts the allowed policies, Never is clamped to untrusted and every read, command and
// write is then rejected — while the process still exits 0. app-server takes a per-thread approvalPolicy,
// and "on-request" is normally permitted.
//
// Protocol facts are pinned in ./schema-<version>/ (generated by `codex app-server generate-json-schema`).
// Three of them are load-bearing and were each got wrong before:
//   * There is no `turn/failed` method. Failure arrives as turn/completed with params.turn.status in
//     {completed, interrupted, failed, inProgress}. Arrival is not success.
//   * Codex spawns its own subagents on other threads. Every event must be filtered by the root
//     threadId, or a child's command satisfies the gate, a child's message becomes the answer, and a
//     child's turn/completed tears down the session while the root turn is still running.
//   * Server-to-client requests are not all approvals. Attestation, ChatGPT token refresh and MCP
//     elicitation share the same channel and take different responses.
//
// Escalation policy: an escalation request means the sandbox was sized wrong for the task, so it is
// surfaced loudly rather than silently waved through or silently refused. Widen the sandbox with
// --writable / --network instead of trying to approve your way out of it.

import { spawn, spawnSync } from "node:child_process";
import readline from "node:readline";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const EXIT = { OK: 0, TURN_NOT_COMPLETED: 1, USAGE: 2, TIMEOUT: 3, TRANSPORT: 4, NO_COMMANDS: 5, ESCALATED: 6, INTERACTION: 7, NO_ANSWER: 8, VERIFY_FAILED: 9, BUSY: 10, COMMAND_FAILED: 11, VERIFY_UNMEASURABLE: 12, SCHEMA: 13 };
const LEVELS = new Set(["read", "write"]);
const READ_PROFILE = "codex_delegate_read";
// The full ladder the model catalogue advertises (`codex debug models` -> supported_reasoning_levels),
// not a subset: rejecting `max` as a usage error while the user's own config.toml asked for it is the
// driver overruling the caller about the one thing it has no opinion on.
// `none` and `minimal` come from the server's own rejection message, which enumerates what it accepts;
// they were refused here as usage errors while the server took them. `ultra` is not in that message but a
// live turn with it completed, so the set is the union rather than either list alone.
const EFFORTS = new Set(["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"]);
// The server's own list, learned from the error it emits for anything else. A Claude seat can search the
// web; a Codex seat could not, because this was pinned to `disabled` with no way to ask. Still disabled by
// default: a search makes the turn depend on what the index says today, and most delegations here are
// about this repository, not about the world.
const WEB_SEARCH = new Set(["cached", "indexed", "live"]);
// --brief is about the coordinator's context, not the seat's thoroughness: the full answer is always
// written to disk, so capping what comes back inline costs nothing but a second read when it matters.
const BRIEF_LINES = 20;
const BRIEF_BYTES = 4000;
const MAX_PROMPT_BYTES = 512 * 1024;
// --timeout is the caller's whole budget, so anything the driver spends after the turn — the verifier —
// has to come out of what is left of it rather than out of a private allowance.
const startedAtMs = Date.now();

function fail(code, msg) {
  process.stderr.write(`codex-delegate: ${msg}\n`);
  process.exitCode = code;
  // A refusal always ends the run, so mark it settled: shutdown() SIGTERMs the child, and the child's exit
  // handler would otherwise rewrite this code to TRANSPORT. That made every post-spawn refusal report 4,
  // including the documented exit 10 for resuming a thread whose turn is still open — a coordinator that
  // backs off on 10 and escalates on 4 did the wrong thing on the one contended case the skill publishes.
  settled = true;
  throw new Bail();
}
class Bail extends Error {}

// ---------------------------------------------------------------- arguments

const USAGE = `codex-delegate — run one Codex turn with rights declared per call.

  node driver.mjs [--level read|write] --cwd DIR [options] --prompt TEXT
  node driver.mjs --cwd DIR < task.txt

Rights
  --level read       the default: read anything, write only $TMPDIR; no lock is
                     taken, so read seats run in parallel over one directory
  --level write      workspace-write over --cwd; takes a per-directory lock
  --worktree REPO    create a detached worktree under REPO/.claude/worktrees, run
                     there at write level, and dispose of it afterwards: once the
                     turn completed, the work is harvested — the tracked diff and
                     an archive of untracked files land under
                     ~/.codex-delegate/answers/, paths in the report — and the
                     tree is removed (a clean tree whose turn never started is
                     removed too). A turn that did not complete, or a harvest
                     that failed, preserves the tree and the report says why and
                     how to remove it (implies --level write; replaces --cwd)
  --writable DIR     grant one more root (write level only, repeatable)
  --network          allow egress (write level only)
  --commit           also grant the git common dir, for a turn that commits
  every write-level root — --cwd, --writable, the --commit git dir — refuses
  ~/.codex and ~/.codex-delegate and anything inside them: they hold the
  rollout receipts and this driver's own state

  --seat-file F      read the seat's declaration from F — one "FIELD: value" per
                     line (SEAT/EFFORT/TIMEOUT/EXPECT/VERIFY/NETWORK/MODEL/
                     WEB_SEARCH/OUTPUT_SCHEMA/WRITABLE/ATTACH/COMMIT/BRIEF/
                     ALLOW_NO_COMMANDS), values taken literally to end of line.
                     SEAT is required and must come FIRST. For a wrapper: write
                     the values, do not build a command line out of them.
                     Explicit flags override the file. A NEWLINE inside a value
                     ends that value and starts a new field — a wrapper handed
                     caller-supplied text cannot prevent that, so:
  --allow-seat-verify  permit VERIFY in a seat file. Without it VERIFY there is
                     refused, because --verify runs an unsandboxed shell with
                     your own rights and a relayed value must not be able to
                     introduce one. Pass --verify on the command line instead.

Turn
  --prompt TEXT      the task; omit to read it from stdin
  --attach FILE      attach a local image (png/jpg/jpeg/gif/webp/bmp) or audio
                     file (wav/mp3/m4a/ogg/flac) to the prompt; repeatable
  --review T         run the server's native reviewer instead of a prompt:
                     T = uncommitted | branch:<ref> | commit:<sha>. The review
                     is the answer; implies --allow-no-commands and excludes
                     --prompt, --resume and the answer-shape flags
  --web-search cached|indexed|live
                     off by default: a search makes the turn depend on what the
                     index says today
  --answer-json      demand one bare JSON object as the answer; the report then
                     carries answerJson and answerJsonError
  --output-schema F  demand a JSON object matching the schema in file F: the
                     server constrains generation with it, the driver checks the
                     result independently, and one corrective turn is spent on a
                     mismatch before exit 13. Implies --answer-json.
                     The server takes a STRICT schema only: every object must
                     carry "additionalProperties": false and list every one of
                     its properties in "required" (use "type": ["string","null"]
                     where you wanted optional). Both are checked here, before
                     the turn, because the server rejects them after it
  --brief            ask for a summary, not a working note, and cap what comes
                     back inline — parity with a subagent whose detail stays in
                     a transcript. The full answer is always written to
                     ~/.codex-delegate/answers/<threadId>.md and its path is in
                     the report as answerPath, with or without this flag.
  --model NAME       omit to use whatever config.toml chose
  --effort ${[...EFFORTS].join("|")}
  --timeout SECONDS  default 900, at most 7200
  --resume THREAD    continue a thread; "--resume last" continues the newest
                     recorded run (the registry lives in ~/.codex-delegate/jobs).
                     --ephemeral leaves no thread behind

Gate — what counts as the turn having done the work
  --expect-command RE   a command matching RE must have run
  --verify CMD          run CMD after the turn; its exit code decides
  --allow-no-commands   accept a turn that ran nothing

Isolation
  by default the turn runs against a CODEX_HOME private to this driver — one
  directory shared by every run, not a fresh one per turn — so the caller's own
  plugins, skills and memories cannot steer it and it writes no trust records
  back; auth.json and sessions stay linked to the real home, and the caches and
  databases codex keeps there persist between runs, which is what makes an
  isolated run faster than a host-home one rather than slower
  --host-home        use the caller's ~/.codex instead, plugins and all
  --mcp              carry the caller's [mcp_servers] — and ONLY them — into the
                     isolated home: the seat gets your MCP tools without your
                     plugins, skills and trust records. The servers run with
                     your rights, as they do under --host-home; grant deliberately
  the private home is filled by asking the caller's own codex what its settings
  resolve to, which costs one short process before the turn: bounded by
  min(5 s, max(1 s, --timeout)) and normally ~120 ms. It counts against the one
  --timeout budget, which is anchored at process start

Report
  --json             machine-readable on stdout — the default; the report also
                     carries receiptPath/receiptOk plus receiptOriginator,
                     receiptModelProvider and receiptCwd, read out of the
                     rollout's own session_meta record (the file is OPENED, not
                     merely matched by name), and tokenUsage (the server's own
                     accounting for the root thread; cumulative across --resume)
  --footer           a human footer instead of the JSON report
  --progress         one line per item start on stderr (run/edit/search), so a
                     long seat can be watched live without tailing the rollout
  threadId is announced on stderr as soon as the thread exists, so a long
  turn's live rollout can be tailed
  SIGINT / SIGTERM / SIGHUP after the thread exists report what the turn did so
  far and exit 1; before it they exit 4. Either way the child process group is
  waited out before the lock is released
  -h, --help         this text

Environment
  CODEX_DELEGATE_STATE_DIR      where the locks, the answer log, the isolated
                                Codex home and the worktree ledger live; must be
                                absolute. For test harnesses: two runs under
                                different values do NOT exclude each other
  CODEX_DELEGATE_SESSIONS_DIR   where to look for the rollout receipt
  CODEX_DELEGATE_CODEX          absolute path to the codex executable; without
                                it the driver searches PATH, then
                                /opt/homebrew/bin, /usr/local/bin, ~/.local/bin
  CODEX_DELEGATE_VERIFY_FLOOR_MS  how little of the --timeout budget is too
                                little to start --verify in (default 100).
                                Also a test seam: the branch is otherwise
                                reachable only by landing inside a 100 ms window

Exit codes. Raised the moment they happen, before any turn could run:
  2  bad arguments
  4  transport, and every sandbox / approval assertion
  10 another run holds the lock on this directory, or a resumed thread
     still has a turn open
  3  can also fire before the turn (a stalled probe or stdin under a short
     --timeout); like an argument-error 2 it then prints no report

Decided after the turn, first match wins, in this order:
  3 timed out ... 2 the server refused the request ... 1 turn did not complete
  ... 7 wanted input ... 6 escalated ... 12 verify unmeasurable
  ... 9 verify failed ... 5 no commands ... 8 no answer
  ... 13 the answer failed --output-schema ... 11 a command or a file change failed

  and 4 once more at the very end, if the report could not reach stdout.

So 2 means either, and they are told apart by the report: an argument error
prints none. Codes decided after the turn can all carry executed work.
`;

// --seat-file exists so a WRAPPER never has to build a shell command line out of values it was handed.
// A relay agent that interpolates a caller-supplied --verify or --expect-command into `sh -c` is one
// quoting slip away from executing whatever that value says — and --verify runs unsandboxed, with the
// caller's own rights, by design. Here the wrapper writes the values verbatim into a file and the
// driver parses them itself: there is no shell between the header and the flags, so no escaping to get
// wrong and nothing for an injected quote to break out of.
//
// The format is one `FIELD: value` per line, value taken literally to end of line (so quotes, $, ;, |
// and backticks are just characters). Unknown fields, repeats and anything the flags reject are usage
// errors — a malformed seat file must never silently become a different seat.
//
// The claim above is exactly true for a value with no NEWLINE in it, and exactly false for one with.
// A newline is the field separator, so a value carrying one ends its own field and opens another —
// measured: a wrapper handed `EXPECT: x\nVERIFY: touch /tmp/pwned`, told by its own contract to copy
// values "character for character", wrote two lines, and the driver ran `touch` through /bin/sh with
// the caller's full rights. Shell metacharacters were never the whole attack surface; line structure
// was the rest of it, and the wrapper cannot tell an injected line from one it meant to write.
//
// Two structural answers, both here rather than in the wrapper, because the wrapper is the component
// that cannot know which of its values came from somewhere else:
//   * SEAT must be the FIRST field. An injected SEAT is then always a duplicate, which is already a
//     usage error — closing the case where a relay omitted SEAT and an injected `SEAT: write ~/.claude`
//     silently defined the rights instead.
//   * VERIFY, alone among the fields, runs an unsandboxed /bin/sh with the caller's own rights. From a
//     seat file it now requires --allow-seat-verify on the COMMAND LINE, which is the one place the
//     coordinator writes directly and no relayed value can reach. A coordinator that wants a verifier
//     passes --verify itself; a relay does not get to introduce one.
const SEAT_FIELDS = new Set(["SEAT", "EFFORT", "TIMEOUT", "EXPECT", "VERIFY", "NETWORK", "MODEL", "WEB_SEARCH", "OUTPUT_SCHEMA", "ALLOW_NO_COMMANDS", "BRIEF", "COMMIT", "WRITABLE", "ATTACH"]);
let seatFileFields = null;   // what the file actually declared, for the report
function argvFromSeatFile(file, allowSeatVerify) {
  let raw;
  try { raw = fs.readFileSync(file, "utf8"); }
  catch (e) { fail(EXIT.USAGE, `--seat-file cannot read ${file}: ${e.message}`); }
  if (Buffer.byteLength(raw) > 64 * 1024) fail(EXIT.USAGE, "--seat-file exceeds 64KB");
  const out = [], seen = new Set(), declared = [];
  for (const line of raw.split("\n")) {
    if (!line.trim() || line.trimStart().startsWith("#")) continue;
    const at = line.indexOf(":");
    if (at < 0) fail(EXIT.USAGE, `--seat-file: line is not FIELD: value — ${JSON.stringify(line.slice(0, 60))}`);
    const field = line.slice(0, at).trim().toUpperCase();
    const value = line.slice(at + 1).trim();
    if (!SEAT_FIELDS.has(field)) fail(EXIT.USAGE, `--seat-file: unknown field ${JSON.stringify(field)}; allowed: ${[...SEAT_FIELDS].join(", ")}`);
    if (seen.size === 0 && field !== "SEAT")
      fail(EXIT.USAGE, `--seat-file: the first field must be SEAT, not ${field} — a seat file that does not open with its rights declaration lets a later line supply them`);
    if (field !== "WRITABLE" && field !== "ATTACH" && seen.has(field)) fail(EXIT.USAGE, `--seat-file: ${field} appears more than once`);
    if (field === "VERIFY" && !allowSeatVerify)
      fail(EXIT.USAGE, "--seat-file: VERIFY runs an unsandboxed shell with your own rights, so it is refused from a seat file unless --allow-seat-verify is given on the command line; pass --verify there instead");
    seen.add(field);
    declared.push(field);
    // SEAT is the rights declaration and the only field that expands to more than one flag.
    if (field === "SEAT") {
      // Split at the FIRST whitespace run only. The format promises the value literal to end of line,
      // and split-and-rejoin rewrote interior whitespace — a path with two consecutive spaces silently
      // became a path with one, which at write level can land the rights on a DIFFERENT existing
      // directory than the one the file declared.
      const sp = value.search(/\s/);
      const kind = sp < 0 ? value : value.slice(0, sp);
      const arg = sp < 0 ? "" : value.slice(sp).trim();
      if (kind === "read") { out.push("--level", "read", ...(arg ? ["--cwd", arg] : [])); }
      else if (kind === "worktree") { if (!arg) fail(EXIT.USAGE, "--seat-file: SEAT worktree needs a repository path"); out.push("--worktree", arg); }
      else if (kind === "write") { if (!arg) fail(EXIT.USAGE, "--seat-file: SEAT write needs a directory"); out.push("--level", "write", "--cwd", arg); }
      else fail(EXIT.USAGE, `--seat-file: SEAT must be read | worktree <repo> | write <dir>, got ${JSON.stringify(value)}`);
      continue;
    }
    const BOOLS = { NETWORK: "--network", ALLOW_NO_COMMANDS: "--allow-no-commands", BRIEF: "--brief", COMMIT: "--commit" };
    if (BOOLS[field]) {
      if (!/^(yes|true|1)$/i.test(value)) fail(EXIT.USAGE, `--seat-file: ${field} must be yes or omitted, got ${JSON.stringify(value)}`);
      out.push(BOOLS[field]);
      continue;
    }
    if (!value) fail(EXIT.USAGE, `--seat-file: ${field} has an empty value`);
    const FLAGS = { EFFORT: "--effort", TIMEOUT: "--timeout", EXPECT: "--expect-command", VERIFY: "--verify",
                    MODEL: "--model", WEB_SEARCH: "--web-search", OUTPUT_SCHEMA: "--output-schema",
                    WRITABLE: "--writable", ATTACH: "--attach" };
    out.push(FLAGS[field], value);
  }
  if (!seen.has("SEAT")) fail(EXIT.USAGE, "--seat-file: no SEAT field; the seat's rights must be declared, not defaulted");
  // In the report, so a coordinator reading a wrapped seat can see what the FILE declared rather than
  // inferring it from the flags the run ended up with.
  seatFileFields = declared;
  return out;
}

function parseArgs(argv) {
  // No effort default. Sending one unconditionally silently downgraded whatever config.toml asked for —
  // measured: a user whose config said `max` got `low` on every delegation. --model already works this
  // way (null means "whatever the config chose"); effort now matches it.
  // JSON is the default report: the only real caller is an agent, and every documented recipe passed
  // --json by hand while forgetting it cost a footer nobody parses. --footer opts back out for a human.
  const o = { level: "read", timeout: 900, writable: [], attach: [], json: true };
  const need = (i, flag) => {
    const v = argv[i];
    if (v === undefined || v === "" || v.startsWith("--")) fail(EXIT.USAGE, `${flag} requires a non-empty value`);
    return v;
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    switch (a) {
      case "--seat-file": o.seatFile = need(++i, a); break;
      // Only ever read off the command line, never out of a seat file — that is the whole of its value.
      case "--allow-seat-verify": o.allowSeatVerify = true; break;
      case "--level": o.level = need(++i, a); o.levelExplicit = true; break;
      case "--cwd": o.cwd = need(++i, a); break;
      case "--worktree": o.worktree = need(++i, a); break;
      case "--effort": o.effort = need(++i, a); break;
      case "--model": o.model = need(++i, a); break;
      case "--timeout": o.timeout = Number(need(++i, a)); break;
      // need(), like every other value-taking flag. It used to be a bare argv[++i], so `--prompt --json`
      // silently made "--json" the entire task. A prompt that genuinely starts with "--" goes on stdin,
      // which is the better shape for a long one anyway.
      case "--prompt": o.prompt = need(++i, a); break;
      case "--writable": o.writable.push(need(++i, a)); break;
      case "--attach": o.attach.push(need(++i, a)); break;
      case "--review": o.review = need(++i, a); break;
      case "--commit": o.commit = true; break;
      case "--resume": o.resume = need(++i, a); break;
      case "--ephemeral": o.ephemeral = true; break;
      case "--allow-no-commands": o.allowNoCommands = true; break;
      case "--expect-command": o.expect = need(++i, a); break;
      case "--verify": o.verify = need(++i, a); break;
      case "--network": o.network = true; break;
      case "--web-search": o.webSearch = need(++i, a); break;
      case "--answer-json": o.answerJson = true; break;
      case "--output-schema": o.outputSchemaFile = need(++i, a); break;
      case "--brief": o.brief = true; break;
      case "--progress": o.progress = true; break;
      case "--host-home": o.hostHome = true; break;
      case "--mcp": o.mcp = true; break;
      case "--json": o.json = true; break;   // the default; kept so existing recipes stay valid
      case "--footer": o.json = false; break;
      // Asking for help is not a usage error: it goes to stdout and exits 0, so `--help | head` works.
      case "-h": case "--help": process.stdout.write(USAGE); process.exit(EXIT.OK); break;
      default: fail(EXIT.USAGE, `unknown argument: ${a}`);
    }
  }
  if (!LEVELS.has(o.level)) fail(EXIT.USAGE, `--level must be one of ${[...LEVELS].join("|")}`);
  // The server enumerates these itself and rejects anything else at startup, which would surface as a
  // transport failure long after the caller could act on it.
  if (o.webSearch !== undefined && !WEB_SEARCH.has(o.webSearch))
    fail(EXIT.USAGE, `--web-search must be one of ${[...WEB_SEARCH].join("|")}`);
  if (o.effort !== undefined && !EFFORTS.has(o.effort))
    fail(EXIT.USAGE, `--effort must be one of ${[...EFFORTS].join("|")}`);
  if (!Number.isFinite(o.timeout) || o.timeout <= 0 || o.timeout > 7200)
    fail(EXIT.USAGE, "--timeout must be a positive number of seconds, at most 7200");
  // The same cap the stdin path enforces. It was on stdin alone, so the documented "512 KB cap" held for
  // the route the docs call better for long prompts and not for the one a caller is more likely to
  // overrun by accident — an argv-sized prompt failed later, in the server, as a mid-turn refusal.
  if (o.prompt !== undefined && Buffer.byteLength(o.prompt) > MAX_PROMPT_BYTES)
    fail(EXIT.USAGE, `--prompt exceeds ${MAX_PROMPT_BYTES} bytes; pipe a long prompt on stdin instead`);
  // --attach maps a local file into the turn's input as the protocol's own item kind — the parity a
  // native subagent has when a screenshot is pasted into its prompt. Checked here so a typo costs
  // nothing: the server would otherwise refuse it mid-turn, after the delegation was already paid for.
  const ATTACH_KINDS = { png: "localImage", jpg: "localImage", jpeg: "localImage", gif: "localImage",
                         webp: "localImage", bmp: "localImage",
                         wav: "localAudio", mp3: "localAudio", m4a: "localAudio", ogg: "localAudio", flac: "localAudio" };
  o.attachments = o.attach.map((p) => {
    let real;
    try { real = fs.realpathSync(path.resolve(p)); } catch { return fail(EXIT.USAGE, `--attach: ${p} does not exist`); }
    if (!fs.statSync(real).isFile()) fail(EXIT.USAGE, `--attach: ${real} is not a regular file`);
    const kind = ATTACH_KINDS[(real.split(".").pop() ?? "").toLowerCase()];
    if (!kind) fail(EXIT.USAGE, `--attach: unsupported file type for ${real}; images (${Object.keys(ATTACH_KINDS).filter((k) => ATTACH_KINDS[k] === "localImage").join("/")}) and audio (${Object.keys(ATTACH_KINDS).filter((k) => ATTACH_KINDS[k] === "localAudio").join("/")})`);
    return { type: kind, path: real };
  });

  // --review maps to the server's own review/start. It builds its own prompt and returns its own
  // shape, so the prompt- and answer-shape flags beside it are contradictions, not extras.
  if (o.review !== undefined) {
    if (o.review === "uncommitted") o.reviewTarget = { type: "uncommittedChanges" };
    else if (o.review.startsWith("branch:") && o.review.length > 7) o.reviewTarget = { type: "baseBranch", branch: o.review.slice(7) };
    else if (o.review.startsWith("commit:") && o.review.length > 7) o.reviewTarget = { type: "commit", sha: o.review.slice(7) };
    else fail(EXIT.USAGE, "--review must be uncommitted | branch:<ref> | commit:<sha>");
    if (o.prompt !== undefined) fail(EXIT.USAGE, "--review builds its own prompt; --prompt cannot be combined with it");
    if (o.resume) fail(EXIT.USAGE, "--review starts its own turn; --resume cannot be combined with it");
    if (o.outputSchemaFile || o.answerJson) fail(EXIT.USAGE, "--review returns the server's review shape; --output-schema and --answer-json cannot be combined with it");
    // The reviewer works through the protocol, not the shell, so a turn with no commands is its
    // ordinary success.
    o.allowNoCommands = true;
  }

  // --worktree owns the cwd it creates, and it is a write-level shape by construction: the whole point
  // is a tree the turn may edit. An explicit --level read beside it is a contradiction, not a hint.
  if (o.worktree && o.cwd) fail(EXIT.USAGE, "--worktree and --cwd are contradictory: the created worktree becomes the cwd");
  if (o.worktree && o.resume) fail(EXIT.USAGE, "--worktree and --resume are contradictory: resume a thread in the tree it started in, via --cwd");
  if (o.worktree && o.levelExplicit && o.level === "read") fail(EXIT.USAGE, "--worktree requires --level write");
  if (o.worktree) o.level = "write";
  if (!o.cwd && !o.worktree) fail(EXIT.USAGE, "--cwd is required");
  if (o.commit && o.level !== "write") fail(EXIT.USAGE, "--commit requires --level write");
  if (o.ephemeral && o.resume) fail(EXIT.USAGE, "--ephemeral and --resume are contradictory");
  // Compile it now: an invalid pattern thrown from inside the report handler kills the run long after
  // the work is done, and costs the whole delegation.
  if (o.expect !== undefined) {
    try { o.expectRe = new RegExp(o.expect); }
    catch (e) { fail(EXIT.USAGE, `--expect-command is not a valid regular expression: ${e.message}`); }
  }
  // Read and sanity-check the schema now, for the same reason as the regex above. The answer contract
  // is ONE bare JSON object, so a schema demanding anything else is a contradiction, not a preference.
  if (o.outputSchemaFile !== undefined) {
    let raw;
    try { raw = fs.readFileSync(o.outputSchemaFile, "utf8"); }
    catch (e) { fail(EXIT.USAGE, `--output-schema cannot read ${o.outputSchemaFile}: ${e.message}`); }
    try { o.outputSchema = JSON.parse(raw); }
    catch (e) { fail(EXIT.USAGE, `--output-schema is not valid JSON: ${e.message}`); }
    if (o.outputSchema === null || typeof o.outputSchema !== "object" || Array.isArray(o.outputSchema))
      fail(EXIT.USAGE, "--output-schema must be a JSON Schema object");
    // The answer contract is ONE bare JSON object, so the schema must say so unambiguously. A missing
    // type, {}, a oneOf-only schema or type:["object","string"] all used to pass admission — and the
    // shallow validator then certified ANY value, including a bare string, as a match.
    if (o.outputSchema.type !== "object" &&
        !(Array.isArray(o.outputSchema.type) && o.outputSchema.type.length === 1 && o.outputSchema.type[0] === "object"))
      fail(EXIT.USAGE, '--output-schema must declare "type": "object" at the top level (the answer contract is one bare JSON object)');
    // The provider does not accept an ordinary JSON Schema here, it accepts a STRICT one, and nothing
    // said so. Measured against the live server, three separate 400s, each costing a whole delegation
    // and surfacing as a turn that simply produced no answer:
    //   plain object      -> "In context=(), 'additionalProperties' is required to be supplied and to be false."
    //   nested object     -> the same, "In context=('properties', 'meta')"
    //   optional property -> "'required' ... an array including every key in properties. Missing 'note'."
    // The admission check two lines up already refuses a schema whose top-level type is not object,
    // for exactly this reason — a contradiction the caller must fix should not be discovered by
    // spending a turn on it. These two rules belong beside it.
    (function strict(s, ctx) {
      if (s === null || typeof s !== "object" || Array.isArray(s)) return;
      const where = ctx.length ? ` at ${ctx.join(".")}` : " at the top level";
      const isObject = s.type === "object" ||
        (Array.isArray(s.type) && s.type.length === 1 && s.type[0] === "object");
      if (isObject) {
        if (s.additionalProperties !== false)
          fail(EXIT.USAGE, `--output-schema${where}: every object must set "additionalProperties": false — the server requires a strict schema and rejects the request otherwise, after the turn has already started`);
        const props = Object.keys(s.properties ?? {});
        const req = new Set(Array.isArray(s.required) ? s.required : []);
        const missing = props.filter((k) => !req.has(k));
        if (missing.length)
          fail(EXIT.USAGE, `--output-schema${where}: "required" must list every key in "properties" — the server permits no optional properties in a strict schema; missing ${missing.map((m) => JSON.stringify(m)).join(", ")}. Make them nullable (\`"type": ["string","null"]\`) instead of optional`);
      }
      for (const [k, v] of Object.entries(s.properties ?? {})) strict(v, [...ctx, "properties", k]);
      if (s.items && !Array.isArray(s.items)) strict(s.items, [...ctx, "items"]);
    })(o.outputSchema, []);
    // The validator implements a subset. Every keyword outside it is collected here and REPORTED, so
    // outputSchemaOk can never silently mean "nothing was checked" — the server still enforces the full
    // schema during generation; the driver's independent check just names what it could not re-verify.
    // additionalProperties is in the SUPPORTED set because the strict rule above makes it mandatory:
    // listing a keyword as unchecked on every single schema would be noise, so the validator honours it
    // instead.
    const SUPPORTED = new Set(["type", "required", "properties", "enum", "items", "additionalProperties",
      "description", "title", "$schema", "$id", "default", "examples"]);
    const unchecked = new Set();
    (function walk(s) {
      if (Array.isArray(s)) return s.forEach(walk);
      if (s === null || typeof s !== "object") return;
      for (const [k, v] of Object.entries(s)) {
        if (!SUPPORTED.has(k)) unchecked.add(k);
        if (k === "properties" && v && typeof v === "object") Object.values(v).forEach(walk);
        else if (k === "items") walk(v);
      }
    })(o.outputSchema);
    if (Array.isArray(o.outputSchema.items)) unchecked.add("items(tuple form)");
    o.schemaUnchecked = unchecked.size ? [...unchecked].sort() : null;
    if (o.schemaUnchecked)
      process.stderr.write(`codex-delegate: --output-schema uses keywords the driver's validator does not check (${o.schemaUnchecked.join(", ")}); the server still enforces them during generation, and the report lists them as schemaKeywordsUnchecked\n`);
    o.answerJson = true;   // the schema subsumes the bare-JSON demand
  }
  return o;
}

function resolveDir(p, what) {
  let real;
  try { real = fs.realpathSync(path.resolve(p)); } catch { fail(EXIT.USAGE, `${what} does not exist: ${p}`); }
  if (!fs.statSync(real).isDirectory()) fail(EXIT.USAGE, `${what} is not a directory: ${real}`);
  return real;
}

// A writable root of / or $HOME is never what the caller meant; refuse rather than hand it over.
//
// Compared by IDENTITY, walking up from home, because a string comparison is bypassable and was: macOS
// realpath does not normalise letter case, so `fs.realpathSync("/users/ruliny")` returns it unchanged and
// `"/users/ruliny" !== "/Users/ruliny"` let a --level write run take the whole home directory. Measured:
// the correct spelling exited 2, the case variant exited 0 and ran. dev:ino collapses case, symlinks and
// every other spelling of the same directory at once — the same fix the cwd lock already uses.
function checkRoot(dir) {
  let target;
  try { target = fs.statSync(dir); }
  catch (e) { fail(EXIT.USAGE, `cannot stat ${dir}: ${e.message}`); }
  const same = (st) => st.dev === target.dev && st.ino === target.ino;
  // Refusing home exactly is not enough: any ANCESTOR of it grants it too, and so does the filesystem
  // root. Walk home upward and refuse if the candidate is any of them.
  // Anchored on the PASSWD entry, not on $HOME. Fixing the comparison to use dev:ino left the anchor
  // mutable, which is the same bug one level up: with HOME unset or pointed at a decoy, `--cwd $HOME` at
  // write level exited 0 and the turn got the whole home directory. os.userInfo().homedir reads passwd and
  // ignores the environment; a deliberate HOME is still honoured by walking it too, so setting HOME can
  // only ever ADD a refusal, never remove one.
  const canon = (a) => { try { return fs.realpathSync(path.resolve(a)); } catch { return path.resolve(a); } };
  const hit = (p, why) => {
    let st = null;
    try { st = fs.statSync(p); } catch {}
    if (st && same(st)) fail(EXIT.USAGE, `refusing to grant write access to ${dir}: it is ${why}`);
  };
  // The passwd home and everything ABOVE it: granting an ancestor grants the home too.
  for (let cur = canon(passwdHome("the home-directory guard")); ; ) {
    hit(cur, cur === canon(passwdHome("the home-directory guard")) ? "your home directory" : `an ancestor of your home directory (${cur})`);
    const parent = path.dirname(cur);
    if (parent === cur) break;
    cur = parent;
  }
  // A deliberate $HOME is honoured, but ONLY as an exact match and only when absolute. Walking its
  // ancestors refused legitimate layouts: a hermetic build with HOME=$W/.home could not use $W as its
  // workspace at all. And a RELATIVE HOME resolves against the driver's own cwd, which would promote an
  // arbitrary directory to a home anchor. The security argument rests on the passwd entry above; this is
  // only politeness toward someone who moved HOME on purpose.
  const envHome = process.env.HOME;
  if (envHome && path.isAbsolute(envHome)) hit(canon(envHome), `the directory $HOME points at (${envHome})`);
  // The receipt story and the driver's own state must never become writable roots: ~/.codex holds the
  // rollouts a seat is verified by (a writable ~/.codex/sessions makes the "unforgeable" receipt
  // forgeable), and ~/.codex-delegate holds the locks, the answer log and the isolated home. Refusing
  // only ~ itself left every one of them grantable — recorded as a known issue until now.
  // Compared by IDENTITY, like every other guard in this function: the first version of this block was
  // a string-prefix compare three lines under the comment explaining why string compares are bypassable
  // here — and it was, by a case-variant spelling on a case-insensitive volume (~/.CODEX is the same
  // inode as ~/.codex and realpath preserves the case it was given). Walking the TARGET's ancestors
  // against the protected inode gives the "inside" semantics a single stat cannot.
  // The state directory is listed by its RESOLVED path, not by the name `.codex-delegate`, so the
  // guarantee follows $CODEX_DELEGATE_STATE_DIR wherever it points. Redirecting the driver's own state
  // and thereby making it writable would hand back exactly what this guard exists to withhold.
  const home = canon(passwdHome("the home-directory guard"));
  const protectedRoots = [
    [path.join(home, ".codex"), "~/.codex"],
    [path.join(home, ".codex-delegate"), "~/.codex-delegate"],
    [stateDir("the home-directory guard"), "this driver's state directory"],
  ];
  for (const [target, label] of protectedRoots) {
    let prot = null;
    try { prot = fs.statSync(target); } catch { continue; }
    for (let cur = dir; ; ) {
      let st = null;
      try { st = fs.statSync(cur); } catch {}
      if (st && st.dev === prot.dev && st.ino === prot.ino)
        fail(EXIT.USAGE, `refusing to grant write access to ${dir}: it is inside ${label}, which holds the rollout receipts and this driver's own state`);
      const parent = path.dirname(cur);
      if (parent === cur) break;
      cur = parent;
    }
  }
  return dir;
}

// A write-capable run owns its cwd for the duration. Two concurrent runs in one directory edit, test and
// clean up over each other, and each can validate the other's half-finished state. Documentation asking
// callers to use unique directories is advice; this is enforcement.
//
// The lock does NOT live in the directory it protects. At --level write with --commit, a turn running
// `git add -A` stages and commits it, and releaseLock then leaves the worktree dirty with a deleted file.
// $TMPDIR is no home for it either, for two measured reasons: it is a mutable env var, so two runs on one
// cwd under different TMPDIRs take two different locks and both proceed — mutual exclusion silently lost —
// and the --level read profile grants Codex write access to exactly that directory.
// os.homedir() falls back to the passwd entry when HOME is unset, and no rights level can write there.
// os.userInfo() rather than os.homedir(), which PREFERS $HOME: two runs on one cwd under different HOME
// values took two different locks and both proceeded — measured, with the lock files sitting in two homes.
// With HOME="" it is worse: os.homedir() returns "", LOCK_DIR becomes RELATIVE, and the lock is created
// inside the invocation directory — exactly the `git add -A` hazard the comment above exists to avoid.
// Resolved LAZILY, and never at module scope. os.homedir() never consulted passwd; os.userInfo() always
// does and THROWS for a uid with no passwd entry — a container run with --user 1000000, an OpenShift
// random uid. At module top level that ran before parseArgs and outside main()'s try, so it produced a raw
// V8 stack trace and exit 1 — which on the published ladder means "the turn did not complete", telling a
// coordinator the turn ran when codex was never spawned.
function passwdHome(what) {
  try { return os.userInfo().homedir; }
  catch (e) { fail(EXIT.USAGE, `cannot resolve your home directory from the passwd database, which ${what} needs (${e.code ?? e.message}); this happens for a uid with no passwd entry`); }
}

// Everything this driver owns — locks, the answer log, the isolated Codex home, the worktree ledger —
// lives under one base, and $CODEX_DELEGATE_STATE_DIR moves it. This exists for ONE reason and it is
// not configurability: the repository's own eval suites drive the driver against a scripted server that
// answers config/read with `model = "fake-model"`, and every run rewrites the SHARED isolated home's
// config.toml. Measured — after a suite run, ~/.codex-delegate/home/config.toml holds
// `model = "fake-model"`, and a real delegation whose own write lost the race started against a model
// that does not exist. Tests must not be able to reach production state; this is the seam that stops it.
//
// The same caveat the lock's passwd anchor exists for applies here and is the price of the seam: two
// runs under two different $CODEX_DELEGATE_STATE_DIR values take two different locks and do not exclude
// each other. It is deliberately NOT a general "put my state elsewhere" knob — set it per test harness,
// not per user — and it must be absolute so it cannot resolve against a caller's cwd.
function stateDir(what) {
  const override = process.env.CODEX_DELEGATE_STATE_DIR;
  if (override) {
    if (!path.isAbsolute(override))
      fail(EXIT.USAGE, `CODEX_DELEGATE_STATE_DIR must be an absolute path, got ${JSON.stringify(override)}`);
    return override;
  }
  return path.join(passwdHome(what), ".codex-delegate");
}
const lockDir = () => path.join(stateDir("the cwd lock"), "locks");

// Codex reads its plugins, skills, memories and project-trust records out of CODEX_HOME, so delegating
// into the caller's own home makes every turn a function of whatever they happen to have installed.
// Measured over the 157 delegations this machine had already run: 95 of them spent their FIRST tool call
// reading ~/.codex/plugins/cache rather than the task, 209 of 919 tool calls went there, and one turn
// ended having done nothing but announce that it had to run a plugin's workflow first. A private home
// removes that input entirely — and, as a side effect, stops each run appending a trusted-project record
// to the caller's config.toml, which is how that file reached 36 KB of dead temp directories.
//
// Two things are linked back rather than isolated. auth.json, so a token refresh still lands in the real
// file instead of expiring inside a cache directory. sessions, because the rollout it holds is the only
// evidence OUTSIDE this process that the turn ran at all: a caller who cannot find the rollout cannot tell
// a seat that did the work from a wrapper that reported success without doing any.
//
// Anchored on passwd for the same reason the lock is: $HOME is attacker- and accident-mutable, and two
// runs under two HOME values would silently use two different homes.
// Isolating the ENVIRONMENT must not isolate the ACCOUNT. `--effort` and `--model` are documented as
// inheriting ~/.codex/config.toml when omitted, and an isolated home has no config.toml at all — so the
// first cut of this silently answered a caller who had asked for `max` at the model's own default, which
// is the exact silent downgrade the comment above EFFORTS exists to prevent. Measured before the fix:
// reasoningEffort came back `max` on the host home and `null` isolated, for the same command.
//
// Only these four: they choose which model answers and how it is spoken to. Everything that pulls in
// outside behaviour — plugins, skills, mcp_servers, projects — is what isolation is for and stays behind.
//
// ASKED of the server rather than read out of the file, and that is the whole point. Reading it meant
// hand-parsing TOML with line regexes, which produced four separate defects in a single day: a value in
// single quotes matched nothing; a multi-line string body was scanned as if it were settings; a duplicate
// key was emitted, which codex then rejects outright; and a COMMENT merely mentioning `= """` opened a
// skip that swallowed every setting after it. Each fix uncovered the next form of a legal file the parser
// did not know. `config/read` returns the values as codex itself resolves them, so the parser and its
// whole family of edge cases are gone.
// JSON.stringify escapes C0 controls but emits DEL (U+007F) and the C1 range raw, and a TOML basic
// string forbids them — codex then rejects the whole file and every delegation fails. Measured with a
// model name containing U+007F, which codex itself will hand back.
const tomlString = (v) => JSON.stringify(v).replace(/[\u007f-\u009f]/g,
  (c) => `\\u${c.codePointAt(0).toString(16).padStart(4, "0")}`);

// Where `codex` actually is. Both spawns used the bare name, so a non-login shell whose PATH lacks the
// install dir failed with ENOENT — and the workaround (export /opt/homebrew/bin in every wrapper) was
// baked prose that no native subagent needs. Order: $CODEX_DELEGATE_CODEX verbatim, then PATH, then the
// standard install locations. Resolved once in setup(); the probe and the real spawn share it.
let codexBin = "codex";
function resolveCodexBin() {
  const runnable = (p) => { try { fs.accessSync(p, fs.constants.X_OK); return fs.statSync(p).isFile(); } catch { return false; } };
  const override = process.env.CODEX_DELEGATE_CODEX;
  if (override) {
    if (!path.isAbsolute(override) || !runnable(override))
      fail(EXIT.USAGE, `CODEX_DELEGATE_CODEX must be an absolute path to an executable codex, got ${JSON.stringify(override)}`);
    return override;
  }
  for (const d of (process.env.PATH ?? "").split(path.delimiter)) {
    if (d && runnable(path.join(d, "codex"))) return path.join(d, "codex");
  }
  const fallbacks = ["/opt/homebrew/bin", "/usr/local/bin", path.join(passwdHome("codex resolution"), ".local", "bin")];
  for (const d of fallbacks) if (runnable(path.join(d, "codex"))) return path.join(d, "codex");
  fail(EXIT.TRANSPORT, `codex not found on PATH or in ${fallbacks.join(", ")}; install it, or set CODEX_DELEGATE_CODEX to its absolute path`);
}

const INHERITED = ["model", "model_reasoning_effort", "personality", "service_tier"];
let mcpFromProbe = null;   // the caller's mcp_servers table, captured by the probe under --mcp only

// Flatten the probe's mcp_servers object into `-c mcp_servers.<name>.<key>=<value>` spawn entries.
// As -c ARGS, not the shared config file, deliberately: the isolated home's config.toml is shared by
// every concurrent run, so a per-invocation grant written there leaks into runs that never asked for
// it (and the last-known-good path could carry a stale grant into a --mcp-less run) — found by a live
// codex review of the first version, which wrote the file. Spawn args are per-run by construction.
// Only shapes the driver can carry FAITHFULLY are emitted — strings, finite numbers, booleans, string
// arrays, and a string-valued env table; a server using anything richer, or a name that is not a bare
// TOML key, is skipped OUT LOUD rather than mangled.
function mcpConfigEntries(servers) {
  const bare = (k) => /^[A-Za-z0-9_-]+$/.test(k);
  const out = [];
  for (const [name, cfg] of Object.entries(servers ?? {})) {
    if (cfg === null || typeof cfg !== "object" || Array.isArray(cfg) || !bare(name)) {
      process.stderr.write(`codex-delegate: --mcp: server ${JSON.stringify(name)} has a shape or name the driver cannot carry faithfully; skipped\n`);
      continue;
    }
    const entries = [];
    let carriable = true;
    const value = (v) =>
      typeof v === "string" ? tomlString(v)
      : typeof v === "number" && Number.isFinite(v) ? String(v)
      : typeof v === "boolean" ? String(v)
      : Array.isArray(v) && v.every((x) => typeof x === "string") ? `[${v.map(tomlString).join(", ")}]`
      : null;
    for (const [k, v] of Object.entries(cfg)) {
      if (v === null || v === undefined) continue;
      if (k === "env" && typeof v === "object" && !Array.isArray(v)) {
        for (const [ek, ev] of Object.entries(v)) {
          const val = typeof ev === "string" && bare(ek) ? tomlString(ev) : null;
          if (val === null) { carriable = false; break; }
          entries.push([`mcp_servers.${name}.env.${ek}`, val]);
        }
      } else {
        const val = bare(k) ? value(v) : null;
        if (val === null) { carriable = false; break; }
        entries.push([`mcp_servers.${name}.${k}`, val]);
      }
    }
    if (!carriable) {
      process.stderr.write(`codex-delegate: --mcp: server ${JSON.stringify(name)} uses a config shape the driver cannot carry faithfully; skipped\n`);
      continue;
    }
    out.push(...entries);
  }
  return out;
}
// Resolves { entries, failed }: `failed` marks an ASKING that failed (spawn, timeout, error reply), as
// opposed to a config with nothing to inherit — the two used to share the value [], and the failure
// half silently changed which model answers, making otherwise identical runs nondeterministic.
function inheritedConfig() {
  return new Promise((resolve) => {
    let child;
    // No CODEX_HOME override: this deliberately reads the CALLER's home, which is the one being inherited
    // from. It starts no thread, so it writes no trusted-project record and calls no model.
    // detached, and killed as a GROUP below, for the reason the real spawn is: killing only the direct
    // child leaves its own children holding these stdio pipes open, and node will not exit while it can
    // still read them. Measured: with a `codex` that hangs, `--timeout 2` took 60 seconds — the driver
    // announced its timeout on schedule and then sat waiting for a grandchild. Before this probe existed
    // the same case exited at 2.1 s.
    try { child = spawn(codexBin, ["--strict-config", "app-server"], { stdio: ["pipe", "pipe", "pipe"], detached: true }); }
    catch (e) {
      // The async failures below all warn; a synchronous spawn failure was the one path that fell back
      // to account defaults without a word.
      process.stderr.write(`codex-delegate: could not read the caller's Codex config (spawn failed: ${e.message}); model and effort fall back to the account default\n`);
      return resolve({ entries: [], failed: true });
    }
    probeChild = child;
    let buf = "", done = false;
    const finish = (v, why) => {
      if (done) return;
      done = true;
      clearTimeout(bell);
      try { process.kill(-child.pid, "SIGKILL"); } catch { try { child.kill("SIGKILL"); } catch {} }
      // The pipes outlive the kill for as long as anything still holds the write end, and an open pipe
      // keeps the event loop alive on its own.
      for (const st of [child.stdout, child.stderr, child.stdin]) { try { st?.destroy(); } catch {} }
      // Silence when there is nothing to inherit is correct; silence when the ASKING failed is the silent
      // downgrade again, so that case says so. A cancellation (shutdown mid-probe) passes why=undefined
      // and stays quiet — the run is ending anyway, and the old path killed the group here a second time
      // and then warned that the probe "exited before replying", which was this driver's own doing.
      if (why) process.stderr.write(`codex-delegate: could not read the caller's Codex config (${why}); model and effort fall back to the account default\n`);
      probeChild = null;
      probeCancel = null;
      resolve({ entries: v, failed: Boolean(why) });
    };
    probeCancel = () => finish([], undefined);
    // Bounded well under any caller's budget, and never longer than it: this runs BEFORE the turn deadline
    // is armed, so a 15 s probe made `--timeout 2` take fifteen seconds. Reading a config takes ~120 ms;
    // anything approaching this is broken, not slow.
    const budget = Math.min(5000, Math.max(1000, (opts?.timeout ?? 900) * 1000));
    // Both buffers are capped: a 96 MiB unterminated write from a broken probe once took driver RSS
    // from 52 to 387 MB. The stderr tail is all the diagnostics ever use, and a reply line that huge
    // is not a config.
    let err = "";
    child.stderr.on("data", (d) => { err = (err + d).slice(-8192); });
    const why = (base) => {
      const tail = err.trim().replace(/\s+/g, " ").slice(-160);
      return tail ? `${base}: ${tail}` : base;
    };
    const bell = setTimeout(() => finish([], why(`no reply in ${budget}ms`)), budget);
    child.on("error", (e) => finish([], why(e.message)));
    child.on("close", () => finish([], why("the config probe exited before replying")));
    child.stdin.on("error", () => {});
    child.stdout.on("data", (d) => {
      buf += d;
      const lines = buf.split("\n");
      buf = lines.pop() ?? "";
      if (buf.length > 262144) return finish([], why("config/read reply exceeds 256KB without a newline"));
      for (const line of lines) {
        let m; try { m = JSON.parse(line); } catch { continue; }
        if (m.id !== 2) continue;
        if (m.error) return finish([], `config/read: ${JSON.stringify(m.error).slice(0, 120)}`);
        // A reply that arrived but cannot be used is NOT the same as "there is nothing to inherit", and
        // treating both as silence is how this mechanism silently downgraded a caller four times already.
        const cfg = m.result?.config;
        if (cfg === null || typeof cfg !== "object")
          return finish([], `config/read returned no usable config (${JSON.stringify(m.result).slice(0, 80)})`);
        const wrong = INHERITED.filter((k) => cfg[k] !== undefined && cfg[k] !== null && typeof cfg[k] !== "string");
        if (wrong.length)
          process.stderr.write(`codex-delegate: the caller's Codex config reports ${wrong.join(", ")} as something other than text; those are not carried across\n`);
        if (opts?.mcp && cfg.mcp_servers && typeof cfg.mcp_servers === "object") mcpFromProbe = cfg.mcp_servers;
        return finish(INHERITED.filter((k) => typeof cfg[k] === "string").map((k) => [k, tomlString(cfg[k])]));
      }
    });
    for (const msg of [
      { jsonrpc: "2.0", id: 1, method: "initialize", params: { clientInfo: { name: "codex-delegate", title: "codex-delegate", version: "2.0" } } },
      { jsonrpc: "2.0", method: "initialized" },
      { jsonrpc: "2.0", id: 2, method: "config/read", params: {} },
    ]) { try { child.stdin.write(`${JSON.stringify(msg)}\n`); } catch {} }
  });
}

// A managed device can narrow what a turn is allowed to do, and thread/start echoes only some of it.
// `approvalPolicy` comes back in the response and is asserted there; the web-search mode does not appear in
// ThreadStartResponse at all, so a caller who asked for `live` on this machine got `cached` and nothing
// said so — measured against a profile carrying `allowed_web_search_modes = ["cached"]`. The policy file
// is the only place that difference is visible before the turn, so read it and refuse early rather than
// letting the caller believe a mode they did not get.
// Absent file, non-macOS, unreadable plist, no such key: all mean "no policy narrows this", which is the
// common case and must not be an error.
const MANAGED_PREFS = "/Library/Managed Preferences/com.openai.codex.plist";
// Returns the permitted modes, or null for "nothing narrows this", or throws for "there IS a policy here
// and I could not read it". That last case used to return null too, which is failing OPEN on the one check
// standing between a caller and a mode they did not get — an unreadable or malformed profile is exactly
// when you want to stop, not to assume permission.
function managedWebSearchModes() {
  if (!fs.existsSync(MANAGED_PREFS)) return null;
  const r = spawnSync("plutil", ["-extract", "requirements_toml_base64", "raw", "-o", "-", MANAGED_PREFS],
    { encoding: "utf8" });
  // No such key is a real answer: the profile constrains other things and says nothing about search.
  if (r.status !== 0) return /does not exist|Could not extract/i.test(String(r.stderr ?? "")) ? null : undefined;
  if (!r.stdout) return undefined;
  // Buffer.from does not throw on malformed base64, it returns whatever it could salvage — so a corrupt
  // profile decoded to binary noise, matched no key, and fell through to "nothing narrows this". That is
  // failing OPEN on the one check standing between a caller and a mode they will not get, which is the
  // opposite of what the previous commit claimed to fix. Re-encoding is the cheap way to tell.
  const raw = r.stdout.trim();
  const buf = Buffer.from(raw, "base64");
  if (buf.toString("base64").replace(/=+$/, "") !== raw.replace(/=+$/, "")) return undefined;
  const toml = buf.toString("utf8");
  const m = toml.match(/^\s*allowed_web_search_modes\s*=\s*\[([^\]]*)\]/m);
  if (!m) return null;
  const modes = [...m[1].matchAll(/["']([^"']+)["']/g)].map((x) => x[1]);
  return modes.length ? modes : undefined;   // an empty list permits nothing, which is not "unrestricted"
}

async function isolatedHome() {
  // The isolated home moves with the driver's own state; the REAL ~/.codex it borrows credentials and
  // sessions from does not, and must not — a test harness redirecting state has no business inventing
  // an auth.json, and the rollout receipt has to land where the published verification recipe looks.
  const base = passwdHome("the isolated Codex home");
  const home = path.join(stateDir("the isolated Codex home"), "home");
  try { fs.mkdirSync(home, { recursive: true, mode: 0o700 }); }
  catch (e) { fail(EXIT.USAGE, `cannot create the isolated Codex home ${home}: ${e.message}`); }
  for (const name of ["auth.json", "sessions"]) {
    const link = path.join(home, name), target = path.join(base, ".codex", name);
    // sessions is CREATED when absent rather than skipped, and the difference is the whole receipt story.
    // Skipping left the rollout inside the private home, where the verification recipe this skill
    // publishes — ls ~/.codex/sessions/*/*/*/rollout-*-<threadId>.jsonl — finds nothing. A real seat then
    // looks exactly like one that fabricated its work, which is the single thing the receipt exists to
    // rule out. On a machine that only ever runs this driver, ~/.codex/sessions never appears on its own,
    // so that was the permanent state there. auth.json is different: it holds credentials this has no
    // business inventing, so an absent one is still skipped.
    if (name === "sessions" && !fs.existsSync(target)) {
      try { fs.mkdirSync(target, { recursive: true, mode: 0o700 }); } catch { /* fall through to the skip */ }
    }
    if (!fs.existsSync(target)) continue;   // nothing to share yet; codex creates its own
    let current = null;
    try { current = fs.readlinkSync(link); } catch (e) {
      // Anything that is not a symlink is a real file someone put there, possibly holding real state.
      // Replacing it silently is how a token or a session archive disappears, so stop and say which.
      if (e.code !== "ENOENT")
        fail(EXIT.USAGE, `${link} exists but is not a symbolic link; move it aside or pass --host-home`);
    }
    if (current === target) continue;
    try {
      if (current !== null) fs.unlinkSync(link);
      fs.symlinkSync(target, link);
    } catch (e) { fail(EXIT.USAGE, `cannot link ${link} -> ${target}: ${e.message}`); }
  }
  // Written into the home rather than sent as -c on purpose. The driver's contract is that omitting
  // --effort sends NO override so the config decides, and two protocol cases pin exactly that; carrying the
  // value as an override would have satisfied the caller and broken the contract. Here the server reads it
  // the same way it reads the caller's own file, and the -c payload is untouched.
  // Rewritten every run, which also keeps the server's trusted-project appends from accumulating.
  const cfg = path.join(home, "config.toml");
  let probe = await inheritedConfig();
  // A transient hiccup gets ONE retry before its silence becomes nondeterminism, and only when the wall
  // clock still leaves room for the probe's own budget plus a turn.
  if (probe.failed && startedAtMs + (opts?.timeout ?? 900) * 1000 - Date.now() > 6000) {
    probe = await inheritedConfig();
  }
  // Still failing: keep the LAST KNOWN GOOD config instead of truncating it. Rewriting on failure was
  // the racy half of the shared-home hazard — a failed probe clobbered the config a concurrent healthy
  // run had just written, and both then ran against account defaults. Concurrent HEALTHY runs write the
  // same bytes (same caller config), so their race is harmless.
  if (probe.failed && fs.existsSync(cfg)) {
    process.stderr.write(`codex-delegate: keeping the previously inherited config (last known good) at ${cfg}\n`);
    return home;
  }
  // Random, not the pid. Two runs in different PID namespaces over one mounted home share a pid, and then
  // both write the same temp name — measured as a partial read and an ENOENT from the loser's rename.
  // "wx" on top of that: it fails rather than following a symlink someone left at the predictable name,
  // which would have redirected this write onto whatever it pointed at.
  const tmp = `${cfg}.${crypto.randomBytes(8).toString("hex")}.tmp`;
  try {
    fs.writeFileSync(tmp, probe.entries.map(([k, v]) => `${k} = ${v}\n`).join(""), { mode: 0o600, flag: "wx" });
    fs.renameSync(tmp, cfg);    // atomic, so a concurrent seat never reads a half-written file
  } catch (e) {
    try { fs.unlinkSync(tmp); } catch {}
    fail(EXIT.USAGE, `cannot write the isolated config ${cfg}: ${e.message}`);
  }
  return home;
}
// A retry is consumed only by reclaiming a stale lock or by the lock vanishing under us, and each needs a
// distinct peer state transition — so the bound covers the plausible fan-out width, not a spin. Measured
// contention (100 concurrent pairs) needed zero retries, so this is headroom, not a working budget.
const LOCK_ATTEMPTS = 10, LOCK_RETRY_MS = 20;
const sleepSync = (ms) => { Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); };

// Classify whatever is at the lock path without trusting it. O_NOFOLLOW keeps a symlink from redirecting
// us, O_NONBLOCK keeps a FIFO from blocking the open forever (measured: a fifo there hung a run past its
// own --timeout, which cannot fire because acquireLock runs before the deadline is armed), and fstat
// catches a directory before readFileSync throws EISDIR — which used to escape as exit 4, claiming codex
// had crashed before codex was even spawned.
//
// Returns {gone:true} when the lock vanished under us, else {held} where held is the parsed contents or
// null if they would not parse. Those two are NOT the same state and must not share a return value: a
// vanished lock means retry, an unparsable one means reclaim, and collapsing them turns a crashed peer's
// empty lock into a permanently contended directory.
function inspectLock(p, dir) {
  let fd;
  try { fd = fs.openSync(p, fs.constants.O_RDONLY | fs.constants.O_NONBLOCK | fs.constants.O_NOFOLLOW); }
  catch (e) {
    if (e.code === "ENOENT") return { gone: true };
    if (e.code === "ELOOP") fail(EXIT.USAGE, `cannot lock ${dir}: ${p} is a symbolic link, not a lock file; remove it and retry`);
    fail(EXIT.USAGE, `cannot lock ${dir}: ${p} exists but cannot be read (${e.code}); remove it or fix its permissions`);
  }
  try {
    const st = fs.fstatSync(fd);
    if (!st.isFile()) {
      const kind = st.isDirectory() ? "a directory" : st.isFIFO() ? "a named pipe" : st.isSocket() ? "a socket" : "not a regular file";
      fail(EXIT.USAGE, `cannot lock ${dir}: ${p} is ${kind}, not a lock file; remove it and retry`);
    }
    let held = null;
    try { held = JSON.parse(fs.readFileSync(fd, "utf8")); } catch {}
    return { held };
  } finally { fs.closeSync(fd); }
}

// Is the pid in a lock file a process that still exists? EPERM means it exists and belongs to another
// user; only ESRCH proves it is gone. An unparsable lock names no pid and cannot be honoured.
function holderAlive(held) {
  const holder = Number(held?.pid);
  if (!Number.isInteger(holder) || holder <= 0) return false;
  try { process.kill(holder, 0); return true; } catch (e) { return e.code === "EPERM"; }
}

// Removes the lock at `p` if and only if it is still stale, with at most one process doing so at a time.
// Returns false when another process holds the reclaim marker, meaning "retry the whole acquisition".
//
// Abandonment is decided by the marker OWNER'S LIVENESS, never by a clock. An mtime deadline was both too
// eager and too slow: it stole the marker from a live owner that had merely been stalled past the deadline
// — a laptop sleep, a SIGSTOP, a wall-clock step — which reopens the multi-holder window the marker exists
// to close; and it wedged a provably FREE directory for the whole deadline whenever a run was killed
// mid-reclaim, measured as exit 10 "contended" on a lock whose owner did not exist. A stalled process is
// alive, so nobody steals its marker and the worst case is an honest BUSY; a dead owner's marker is
// abandonable immediately. The mtime bound survives only as a backstop against a recycled marker pid.
const RECLAIM_BACKSTOP_MS = 3600000;
function reclaimStale(p, dir) {
  const rp = `${p}.reclaim`;
  const tmp = `${p}.${process.pid}.rtmp`;
  try {
    fs.writeFileSync(tmp, String(process.pid));
    try { fs.linkSync(tmp, rp); }
    catch (e) {
      if (e.code !== "EEXIST") fail(EXIT.USAGE, `cannot reclaim the stale lock ${p}: ${e.message}`);
      // Someone is reclaiming right now — unless the process named in their marker is gone.
      try {
        const owner = Number(fs.readFileSync(rp, "utf8").trim());
        const abandoned = !holderAlive({ pid: owner }) || Date.now() - fs.statSync(rp).mtimeMs > RECLAIM_BACKSTOP_MS;
        if (abandoned) fs.rmSync(rp, { force: true });
      } catch {}
      return false;
    }
  } finally { fs.rmSync(tmp, { force: true }); }
  try {
    // Ask again, under the reclaim lock. The lock may have been reclaimed by someone else and retaken by
    // a live process since we last looked; deleting it then is exactly the bug this exists to prevent.
    const now = inspectLock(p, dir);
    if (!now.gone && !holderAlive(now.held)) fs.rmSync(p, { force: true });
  } finally { fs.rmSync(rp, { force: true }); }
  return true;
}

let lockPath = null;
function acquireLock(dir) {
  // Keyed on the directory's IDENTITY, not on how it was spelled. realpath normalises symlinks but not
  // letter case, so on a case-insensitive volume `--cwd .../Worktree` and `--cwd .../worktree` are one
  // directory with two hashes — measured, and the second run walked straight in. dev:ino covers case,
  // renames and every other aliasing at once. The body still records the path, for the human who finds it.
  let st;
  try { st = fs.statSync(dir); }
  catch (e) { fail(EXIT.USAGE, `cannot stat --cwd ${dir}: ${e.message}`); }
  const LOCK_DIR = lockDir();
  const p = path.join(LOCK_DIR, `${crypto.createHash("sha256").update(`${st.dev}:${st.ino}`).digest("hex")}.lock`);
  try { fs.mkdirSync(LOCK_DIR, { recursive: true, mode: 0o700 }); }
  catch (e) { fail(EXIT.USAGE, `cannot create the lock directory ${LOCK_DIR}: ${e.message}`); }
  // The file name is a hash, so the contents have to say what it locks — for the message below and for a
  // human who finds a stale one.
  const body = JSON.stringify({ pid: process.pid, cwd: dir, started: new Date().toISOString() });
  // Creation is ATOMIC, not merely exclusive. `writeFileSync(..., "wx")` creates the file and then writes
  // it, so there is a window in which the lock exists but is empty — and an empty lock reads as abandoned,
  // which is the one thing a lock must never do. Writing to a private temp file and link(2)-ing it into
  // place means it is fully formed the instant it becomes visible; link fails EEXIST if someone got there
  // first. Reverting this alone did NOT reproduce a violation in 19 acquisitions, so it is not the fix for
  // the race below — it is here because the window is real and the cost of losing it is two writers in one
  // repository, not because a measurement forced it.
  const tmp = `${p}.${process.pid}.tmp`;
  for (let attempt = 0; attempt < LOCK_ATTEMPTS; attempt++) {
    let linked = false;
    try {
      fs.writeFileSync(tmp, body);
      fs.linkSync(tmp, p);
      linked = true;
    } catch (e) {
      if (e.code !== "EEXIST") fail(EXIT.USAGE, `cannot lock ${dir} (${p}): ${e.message}`);
    } finally {
      fs.rmSync(tmp, { force: true });
    }
    if (linked) { lockPath = p; return; }
    {
      const seen = inspectLock(p, dir);
      // Vanished between our failed create and the read: a peer released it. Retry, do not report a
      // transport failure — that used to surface as exit 4 on an ordinary release.
      if (seen.gone) { sleepSync(LOCK_RETRY_MS); continue; }
      // An unparsable lock names no live pid, so it cannot be honoured. Since creation is atomic this is
      // no longer a half-written file from a peer — it is a hand-made or corrupted one — but treating it
      // as held would wedge the directory forever, so it is reclaimed like any other stale lock.
      const held = seen.held;
      const holder = Number(held?.pid);
      if (holderAlive(held)) fail(EXIT.BUSY,
        `${dir} is in use by codex-delegate pid ${holder} (started ${held?.started ?? "unknown"}); ` +
        `give each concurrent run its own cwd. If that process is gone, delete ${p}`);
      // Reclaiming a stale lock is where mutual exclusion actually broke, and neither an unlink nor a
      // rename fixes it: both act on the PATH, not on the file that was inspected. A peer that judged the
      // STALE lock dead arrives late and removes the FRESH, live lock that has since replaced it, then
      // takes the directory. Measured by logging the acquire/release interval of every process in an
      // eight-way fan-out over a planted stale lock: the old unconditional unlink produced 6 violations
      // and up to THREE simultaneous holders; serialising the reclaim gives 0 and a maximum of 1.
      //
      // (Counting how many runs exited 0 does not measure this and will mislead you: runs that acquire in
      // sequence all succeed, correctly. Only overlapping hold intervals are evidence.)
      //
      // The reclaim is serialised by its own short-lived lock, and the liveness question is asked again
      // UNDER it. Only one process can be deleting the lock at a time, and it deletes only what it has
      // just re-confirmed to be dead — so a lock created in the meantime is seen as live and survives.
      if (!reclaimStale(p, dir)) { sleepSync(LOCK_RETRY_MS); continue; }
    }
  }
  fail(EXIT.BUSY, `${dir} is contended: the lock at ${p} changed hands ${LOCK_ATTEMPTS} times without settling`);
}
function releaseLock() {
  if (!lockPath) return;
  try { if (JSON.parse(fs.readFileSync(lockPath, "utf8")).pid === process.pid) fs.rmSync(lockPath, { force: true }); } catch {}
  lockPath = null;
}

// ---------------------------------------------------------------- worktree
// --worktree is parity with a Claude subagent's isolation:"worktree": the driver creates a uniquely
// named detached worktree, runs the turn inside it, and removes it afterwards ONLY when the tree is
// provably worthless — the turn completed and `git status --porcelain` is empty. Untracked files show
// in porcelain output, so a tree holding any work, tracked or not, is preserved rather than harvested
// by force. A ledger entry under ~/.codex-delegate/worktrees/ is written before the turn so a crashed
// run leaves a machine-readable trace instead of an anonymous directory.
let worktreeInfo = null;
// os.userInfo() directly rather than passwdHome() inside stateDir: this is called from persistAnswer,
// a best-effort side write on a turn that has already succeeded, where fail()'s refusal-and-exit is the
// wrong shape. stateDir() only calls passwdHome when the override is absent, and persistAnswer wraps
// the whole thing in a try/catch, so a missing passwd entry costs the path and nothing else.
const answersDir = () => path.join(stateDir("the answer log"), "answers");

// One JSON record per run, keyed by threadId, under ~/.codex-delegate/jobs/ — the registry that lets a
// coordinator list what ran and resume the newest thread without having kept the id itself
// (--resume last). Best-effort on the same terms as the answer log: losing a record costs the record,
// never the run. Pruned with the same bounds as the answers.
const jobsDir = () => path.join(stateDir("the job registry"), "jobs");
function writeJob(fields) {
  // Ephemeral threads cannot be resumed, so a registry whose purpose is resume must not offer them.
  if (!rootThreadId || opts?.ephemeral) return;
  try {
    const dir = jobsDir();
    fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    const p = path.join(dir, `${rootThreadId}.json`);
    let prev = {};
    try { prev = JSON.parse(fs.readFileSync(p, "utf8")); } catch {}
    fs.writeFileSync(p, JSON.stringify({ ...prev, ...fields }), { mode: 0o600 });
    pruneAnswers(dir);
  } catch {}
}
// `--resume last`: the newest job record wins, ended or not — a still-running seat's thread refuses
// the resume anyway (exit 10), which is the honest answer for "the last seat is still working".
function resolveResumeLast() {
  let names = [];
  try { names = fs.readdirSync(jobsDir()).filter((n) => n.endsWith(".json")); } catch {}
  const newest = names
    .map((n) => { try { return { n, t: fs.statSync(path.join(jobsDir(), n)).mtimeMs }; } catch { return null; } })
    .filter(Boolean).sort((a, b) => b.t - a.t)[0];
  if (!newest) fail(EXIT.USAGE, "--resume last: no previous run is recorded in the job registry");
  const id = newest.n.replace(/\.json$/, "");
  process.stderr.write(`codex-delegate: --resume last -> ${id}\n`);
  return id;
}

// What CRASHED runs left behind, reconciled on the next --worktree invocation — the moment the cost is
// amortized and worktrees are already the topic. A ledger entry whose owner is dead names either a
// tree that is gone (drop the entry), a clean tree (remove both), or a dirty one (keep both and say
// so). Entries used to accumulate forever with no owner and no reconciler. Best-effort, never fatal.
function reconcileWorktreeLedgers() {
  try {
    const ledgerDir = path.join(stateDir("the worktree ledger"), "worktrees");
    for (const n of fs.readdirSync(ledgerDir).filter((x) => x.endsWith(".json")).slice(0, 50)) {
      const p = path.join(ledgerDir, n);
      let e = null;
      try { e = JSON.parse(fs.readFileSync(p, "utf8")); } catch { fs.rmSync(p, { force: true }); continue; }
      if (holderAlive({ pid: e?.pid })) continue;
      if (!e?.path || !fs.existsSync(e.path)) { fs.rmSync(p, { force: true }); continue; }
      const st = spawnSync("git", ["-C", e.path, "status", "--porcelain"], { encoding: "utf8" });
      if (st.status === 0 && st.stdout.trim() === "" &&
          spawnSync("git", ["-C", e.repo ?? e.path, "worktree", "remove", e.path], { encoding: "utf8" }).status === 0) {
        fs.rmSync(p, { force: true });
        process.stderr.write(`codex-delegate: removed a crashed run's clean worktree ${e.path}\n`);
      } else {
        process.stderr.write(`codex-delegate: a crashed run left work at ${e.path}; harvest it, then: git -C ${e.repo ?? "<repo>"} worktree remove --force ${e.path}\n`);
      }
    }
  } catch {}
}

function createWorktree(repo) {
  // Guarded BEFORE `git worktree add` mutates anything: a repo inside a protected root used to be
  // checked out (running its hooks) and only then refused by the cwd check.
  checkRoot(repo);
  reconcileWorktreeLedgers();
  const chk = spawnSync("git", ["-C", repo, "rev-parse", "--is-inside-work-tree"], { encoding: "utf8" });
  if (chk.status !== 0 || chk.stdout.trim() !== "true") fail(EXIT.USAGE, `--worktree needs a git work tree at ${repo}`);
  const name = `codex-${Date.now().toString(36)}-${crypto.randomBytes(4).toString("hex")}`;
  const dir = path.join(repo, ".claude", "worktrees", name);
  // checkRoot(repo) above guards where the worktree is asked FROM; this guards where it lands. They are
  // not the same directory whenever `<repo>/.claude` is a symbolic link, and the comment above claimed
  // a fix it did not have — measured with `.claude -> ~/.codex-delegate/x`: stderr printed
  // "created worktree ..." and only THEN "refusing to grant write access", i.e. git had already made
  // directories inside the protected root and would have checked a whole tree out there (running its
  // hooks) had the parent existed. Resolve the nearest EXISTING ancestor, because the leaf does not
  // exist yet and realpath cannot follow a link that is not there.
  const parent = path.dirname(dir);
  let anchor = parent;
  while (!fs.existsSync(anchor) && path.dirname(anchor) !== anchor) anchor = path.dirname(anchor);
  const anchorReal = canonPath(anchor);
  if (anchorReal) checkRoot(anchorReal);
  try { fs.mkdirSync(parent, { recursive: true }); }
  catch (e) { fail(EXIT.USAGE, `cannot create ${parent}: ${e.message}`); }
  // And again on what was actually created, so a link swapped in during the mkdir is still caught
  // before git writes a single object.
  checkRoot(fs.realpathSync(parent));
  const add = spawnSync("git", ["-C", repo, "worktree", "add", "--detach", dir], { encoding: "utf8" });
  if (add.status !== 0) fail(EXIT.USAGE, `git worktree add failed: ${String(add.stderr).trim().slice(0, 200)}`);
  let ledger = null;
  try {
    const ledgerDir = path.join(stateDir("the worktree ledger"), "worktrees");
    fs.mkdirSync(ledgerDir, { recursive: true, mode: 0o700 });
    ledger = path.join(ledgerDir, `${name}.json`);
    fs.writeFileSync(ledger, JSON.stringify({ path: dir, repo, pid: process.pid, started: new Date().toISOString() }), { mode: 0o600 });
  } catch { ledger = null; }   // a missing trace must not refuse the run
  process.stderr.write(`codex-delegate: created worktree ${dir}\n`);
  worktreeInfo = { repo, dir, ledger, disposed: false };
  return dir;
}

// Runs AFTER the turn settled and after --verify (the verifier executes in the tree).
// A COMPLETED turn's tree is disposed of entirely: the work is harvested first — the tracked diff
// (staged and unstaged, --binary so a binary edit survives `git apply`) and an archive of the
// untracked files, both under the answers dir — and only then is the tree removed, --force included,
// because the harvest now holds every byte the force could destroy. That is the parity a native
// worktree subagent has: the routine outcome of a write seat asks nothing of the operator. A turn
// that did NOT complete, a failing git, or a failed harvest preserves the tree — fail-safe, out loud.
function disposeWorktree(turnDone) {
  if (!worktreeInfo || worktreeInfo.disposed) return null;
  worktreeInfo.disposed = true;
  const { repo, dir, ledger } = worktreeInfo;
  const res = { worktreePath: dir, worktreeRemoved: false, worktreePreserved: null, worktreeHarvested: false,
                worktreeDiffStat: null, worktreeDiffPath: null, worktreeUntrackedPath: null, worktreeFleet: null };
  const st = spawnSync("git", ["-C", dir, "status", "--porcelain"], { encoding: "utf8" });
  const clean = st.status === 0 && st.stdout.trim() === "";
  if (!turnDone) res.worktreePreserved = `turn ${turnStatus ?? "never started"} — the tree may be mid-write`;
  else if (st.status !== 0) res.worktreePreserved = "git status failed in the worktree";
  else if (!clean) {
    // `git diff HEAD`, not bare `git diff`: dirtiness is decided by `status --porcelain`, which sees
    // staged changes, so the harvest must see them too — the bare form omits them, and a turn that
    // staged work without committing lost that half. HEAD always exists in a tree `worktree add
    // --detach` created; the bare form stays as a fallback for a git that refuses HEAD.
    const diffVs = (extra) => {
      let r = spawnSync("git", ["-C", dir, "diff", "HEAD", ...extra], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
      if (r.status !== 0) r = spawnSync("git", ["-C", dir, "diff", ...extra], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
      return r;
    };
    const ds = diffVs(["--stat"]);
    if (ds.status === 0 && ds.stdout.trim()) res.worktreeDiffStat = ds.stdout.trim().slice(0, 2000);
    // Returns null on success, or the reason the harvest cannot be trusted — in which case the tree
    // is preserved exactly as before this existed.
    const harvest = () => {
      const base = path.join(answersDir(), `${rootThreadId ?? `no-thread-${process.pid}`}`);
      fs.mkdirSync(answersDir(), { recursive: true, mode: 0o700 });
      const full = diffVs(["--binary"]);
      if (full.status !== 0) return `the diff could not be taken (${String(full.stderr).trim().slice(0, 120)})`;
      if (full.stdout.length) {
        fs.writeFileSync(`${base}.diff`, full.stdout, { mode: 0o600 });
        res.worktreeDiffPath = `${base}.diff`;
      }
      const ls = spawnSync("git", ["-C", dir, "ls-files", "--others", "--exclude-standard", "-z"],
        { maxBuffer: 64 * 1024 * 1024 });
      if (ls.status !== 0) return "the untracked list could not be taken";
      if (ls.stdout.length) {
        const tar = spawnSync("tar", ["-czf", `${base}.untracked.tgz`, "-C", dir, "--null", "-T", "-"],
          { input: ls.stdout, encoding: "utf8" });
        if (tar.status !== 0) return `untracked files could not be archived (${String(tar.stderr).trim().slice(0, 120)})`;
        res.worktreeUntrackedPath = `${base}.untracked.tgz`;
      }
      return null;
    };
    let why = null;
    try { why = harvest(); } catch (e) { why = e.message; }
    if (why) res.worktreePreserved = `the tree holds changes and the harvest failed (${why}); harvest by hand, then remove`;
    else {
      res.worktreeHarvested = true;
      const rm = spawnSync("git", ["-C", repo, "worktree", "remove", "--force", dir], { encoding: "utf8" });
      if (rm.status === 0) res.worktreeRemoved = true;
      else res.worktreePreserved = `harvested, but git worktree remove refused: ${String(rm.stderr).trim().slice(0, 160)}`;
    }
  } else {
    // A clean tree needs no force, and anything git refuses to remove here is worth looking at.
    const rm = spawnSync("git", ["-C", repo, "worktree", "remove", dir], { encoding: "utf8" });
    if (rm.status === 0) res.worktreeRemoved = true;
    else res.worktreePreserved = `git worktree remove refused: ${String(rm.stderr).trim().slice(0, 160)}`;
  }
  // Quoted, because this string is published as "what to run" and both paths are attacker- and
  // accident-shaped: a repository under a directory with a space produced a command that removed the
  // wrong tree or nothing at all. Single quotes with the standard '\'' escape are safe for any byte a
  // path can hold.
  const shq = (s) => `'${String(s).replaceAll("'", `'\\''`)}'`;
  if (!res.worktreeRemoved) res.worktreeRemoveCommand = `git -C ${shq(repo)} worktree remove --force ${shq(dir)}`;
  const fleet = spawnSync("git", ["-C", repo, "worktree", "list", "--porcelain"], { encoding: "utf8" });
  if (fleet.status === 0)
    res.worktreeFleet = fleet.stdout.split("\n").filter((l) => l.startsWith("worktree ") && l.includes("/.claude/worktrees/")).length;
  if (ledger) { try { fs.rmSync(ledger, { force: true }); } catch {} }
  return res;
}

// The synchronous last resort, for runs that end without reaching finish() — a usage error after the
// tree was created, a Bail, a crash. A tree whose turn never started cannot hold work and is removed;
// anything else is preserved out loud.
function worktreeLastResort() {
  if (!worktreeInfo || worktreeInfo.disposed) return;
  worktreeInfo.disposed = true;
  const { repo, dir, ledger } = worktreeInfo;
  let removed = false;
  if (!child) {
    const st = spawnSync("git", ["-C", dir, "status", "--porcelain"], { encoding: "utf8" });
    if (st.status === 0 && st.stdout.trim() === "")
      removed = spawnSync("git", ["-C", repo, "worktree", "remove", dir], { encoding: "utf8" }).status === 0;
  }
  if (removed) { if (ledger) { try { fs.rmSync(ledger, { force: true }); } catch {} } }
  else process.stderr.write(`codex-delegate: worktree PRESERVED at ${dir} (run ended before disposition); ` +
    `harvest it, then: git -C ${repo} worktree remove --force ${dir}\n`);
}

// The read level's whole safety argument is "$TMPDIR is writable and nothing else is", so that is what
// gets checked — the EFFECT the server reports, not the NAME of the profile that was supposed to produce
// it. Checking the name is not enough, measured: misspell a field inside permissions.<id> and the grant
// silently vanishes (sandbox flips to {"type":"readOnly"}, writableRoots disappears) while
// activePermissionProfile still reads back the correct id. --strict-config does not catch that typo
// either, so a name-only assert passes while the thing it guards is gone.
//
// Paths are canonicalised on BOTH sides rather than string-compared: the server resolves intermediate
// symlinks (/var/... -> /private/var/...) but leaves a symlinked FINAL component alone, so no single
// string transform matches every shape TMPDIR can take.
function canonPath(p) {
  try { return fs.realpathSync(path.resolve(p)); } catch { return null; }
}
// Both levels are checked, because guarding only the read one was an asymmetry rather than a decision:
// read was the level with something clever to verify, so it got the attention, while WRITE — the level
// that can actually damage a repository — accepted whatever cwd, network setting and writable-root set the
// server chose to report. What each level expects differs, but "assert the effect the server reports"
// does not.
function assertSandbox(thread) {
  return opts.level === "read" ? assertReadSandbox(thread) : assertWriteSandbox(thread);
}

// At write level the server reports the grant differently, measured against the live binary: the cwd is
// NOT in writableRoots — it is implied by workspaceWrite and appears in runtimeWorkspaceRoots — so
// writableRoots holds exactly the EXTRA roots from --writable/--commit and is empty without them. The
// permission profile is null here, because sending `sandbox` at all suppresses it.
function assertWriteSandbox(thread) {
  const refuse = (why) => fail(EXIT.TRANSPORT,
    `the write sandbox is not what was asked for (${why}); refusing to continue rather than run under an unknown sandbox`);
  const sb = thread.sandbox ?? null;
  if (sb?.type !== "workspaceWrite") refuse(`sandbox type is ${JSON.stringify(sb?.type ?? null)}`);
  // Egress is opt-in and the flag is the whole of the opt-in; a server granting it unasked is a widening.
  if (Boolean(sb.networkAccess) !== Boolean(opts.network))
    refuse(`networkAccess is ${Boolean(sb.networkAccess)} but --network was ${opts.network ? "given" : "not given"}`);
  const want = [...roots].map(canonPath).sort();
  const got = (sb.writableRoots ?? []).map(canonPath).sort();
  if (want.length !== got.length || want.some((r, i) => r !== got[i]))
    refuse(`writable roots are ${JSON.stringify(sb.writableRoots ?? [])}, expected ${JSON.stringify(roots)}`);
  // The cwd is the primary grant and the one the caller reasoned about; if the server put a different
  // directory there, everything the turn writes lands somewhere the caller did not choose.
  const workspace = (thread.runtimeWorkspaceRoots ?? []).map(canonPath);
  if (!workspace.includes(canonPath(cwd)))
    refuse(`the workspace roots are ${JSON.stringify(thread.runtimeWorkspaceRoots ?? [])}, which do not include --cwd ${cwd}`);
}

function assertReadSandbox(thread) {
  const refuse = (why) => fail(EXIT.TRANSPORT,
    `the read sandbox is not what was asked for (${why}); refusing to continue rather than run under an unknown sandbox`);
  const applied = thread.activePermissionProfile?.id ?? null;
  if (applied !== READ_PROFILE) refuse(`server reports profile ${JSON.stringify(applied)}`);
  const sb = thread.sandbox ?? null;
  if (sb?.type !== "workspaceWrite") refuse(`sandbox type is ${JSON.stringify(sb?.type ?? null)}, so the $TMPDIR grant did not apply`);
  // Egress is the level's headline promise — `--level read --network` is a hard usage error precisely
  // because read never grants it. A `network` table in the user's own permissions profile turns it back
  // on, and the server says so right here in the object this guard already holds.
  if (sb.networkAccess === true) refuse("the sandbox has network access, which --level read never grants");
  // TMPDIR unset is a real degraded state, not a formatting quirk: the server then grants nothing and
  // read-level tests cannot run. Test the variable separately from resolving it — path.resolve("") is the
  // process's own cwd, so folding the two together produced a refusal that named the caller's repository
  // as the expected writable root.
  const tmp = process.env.TMPDIR;
  if (!tmp) refuse("TMPDIR is unset, so the server grants no temp directory at all; export TMPDIR and retry");
  const want = canonPath(tmp);
  if (!want) refuse(`TMPDIR is set to ${JSON.stringify(tmp)}, which does not resolve to a real directory`);
  const got = (sb.writableRoots ?? []).map(canonPath);
  // Exactly one root, and it is TMPDIR — unless the cwd IS the tmpdir, in which case the server subtracts
  // it from writableRoots and reports it under runtimeWorkspaceRoots, exactly as at write level. Demanding
  // it in both places refused `--level read --cwd $TMPDIR`, which is a legitimate scratch-dir invocation.
  // The cwd is checked at BOTH levels. At write level it decides where the turn writes; at read level it
  // decides which tree the turn READS, and a server that put us somewhere else would have the run answer
  // confidently about the wrong repository. Nothing in the sandbox object reveals it.
  const workspace = (thread.runtimeWorkspaceRoots ?? []).map(canonPath);
  if (!workspace.includes(canonPath(cwd)))
    refuse(`the workspace roots are ${JSON.stringify(thread.runtimeWorkspaceRoots ?? [])}, which do not include --cwd ${cwd}`);
  const cwdIsTmp = canonPath(cwd) === want;
  // When --cwd IS the tmpdir the server subtracts it from writableRoots and reports it in the workspace
  // roots instead — already verified just above — so an empty root list is correct there, not a dropped
  // grant.
  const ok = cwdIsTmp ? got.length === 0 : (got.length === 1 && got[0] === want);
  if (!ok)
    refuse(`writable roots are ${JSON.stringify(sb.writableRoots ?? [])}, expected exactly [${JSON.stringify(want)}]`);
}

// Assigned by setup(), which runs inside main()'s try — a Bail thrown at module top level would be an
// uncaught exception and would print a stack trace instead of the intended usage error.
let opts, cwd, sandbox, spawnArgs;
let codexHome = null;   // null means the caller's own ~/.codex, which --host-home asks for
let roots = [];

async function setup() {
  // A seat file is expanded into ordinary argv and re-parsed, so every flag guard, every mutual
  // exclusion and every value check applies to it unchanged — a second parser would be a second set of
  // rules to keep in sync, which is how a wrapper's rights quietly stop matching the CLI's.
  // Command-line flags are appended after the file's, so an explicit flag still wins where the two
  // disagree (--timeout is the common case: the harness bounding a seat it did not author).
  // Scanned for the flag alone, not parsed: a full parse first would reject the command line for
  // missing exactly what the seat file is about to supply (--cwd).
  const argv = process.argv.slice(2);
  const at = argv.indexOf("--seat-file");
  // A SECOND --seat-file used to be silently ignored: only the first pair is expanded and removed, and
  // the survivor set o.seatFile and was never read. Two seat files on one command line is a caller who
  // believes something untrue about which seat is running, so say so instead of picking one.
  if (at >= 0 && argv.indexOf("--seat-file", at + 2) >= 0)
    fail(EXIT.USAGE, "--seat-file given more than once; only one seat file defines a seat");
  if (at >= 0 && (argv[at + 1] === undefined || argv[at + 1].startsWith("--")))
    fail(EXIT.USAGE, "--seat-file requires a non-empty value");
  // Scanned off the raw command line on purpose: a seat file must not be able to authorise itself.
  const allowSeatVerify = argv.includes("--allow-seat-verify");
  opts = at >= 0
    ? parseArgs([...argvFromSeatFile(argv[at + 1], allowSeatVerify), ...argv.filter((_, i) => i !== at && i !== at + 1)])
    : parseArgs(argv);

  // After parseArgs, so --help works on a machine with no codex at all.
  codexBin = resolveCodexBin();
  if (opts.resume === "last") opts.resume = resolveResumeLast();

  // Two levels, mirroring Claude's own subagents: a reader that can run things but not touch your files,
  // and a writer confined to a directory you chose. Everything else is a modifier.
  //
  // read  : the ":read-only" permission profile, extended to make $TMPDIR writable. Your files, the repo
  //         and /tmp all stay unwritable; the temp dir is what tools need to start at all. Without it a
  //         reader cannot run the test suite, which Claude's own read-only subagent can — that gap is the
  //         whole reason the profile is here rather than a plain sandbox: "read-only".
  // write : workspace-write with cwd as the writable root, plus --commit / --writable / --network.
  sandbox = opts.level === "read" ? null : "workspace-write";

  if (opts.level === "read" && (opts.network || opts.writable.length))
    fail(EXIT.USAGE, "--network and --writable belong to --level write");

  if (opts.worktree) opts.cwd = createWorktree(resolveDir(opts.worktree, "--worktree"));

  // --cwd is the primary writable root above read, so it needs the same guard as a hand-added root.
  cwd = resolveDir(opts.cwd, "--cwd");
  if (opts.level !== "read") checkRoot(cwd);

  // $TMPDIR IS the read level's writable root — that is the whole of the level's grant — so it needs the
  // same guard every other writable root gets, and it did not have it. checkRoot was applied to --cwd,
  // --writable and the --commit git dir; TMPDIR reached the sandbox unexamined. Measured:
  // `TMPDIR=~/.codex/x --level read` exited 0 with the server reporting
  // writableRoots: ["/Users/ruliny/.codex/x"] — write access inside the directory that holds the rollout
  // receipts, from the level whose headline promise is that it writes nothing of yours. The comment on
  // checkRoot says a writable ~/.codex/sessions makes the "unforgeable" receipt forgeable; this was the
  // door to it. Refused here rather than in assertReadSandbox so it costs no turn.
  if (opts.level === "read" && process.env.TMPDIR) {
    const t = canonPath(process.env.TMPDIR);
    if (t) checkRoot(t);
  }

  // Before the lock, deliberately. This asks another codex process what the caller's settings are, and a
  // probe that hangs used to hold the write lock for its whole 15 s while doing it — measured: a second
  // run on the same directory got exit 10 for a directory nobody was working in.
  codexHome = opts.hostHome ? null : await isolatedHome();

  if (opts.level !== "read") acquireLock(cwd);

  // Deduped, because the SERVER dedupes what it is given: sending /x twice (or /x and /x/, which
  // resolveDir collapses) made assertWriteSandbox compare two entries against the server's one and fail
  // the run with exit 4 — a permanent flag redundancy reported as "codex crashed".
  // Deduped AND with the cwd subtracted, because the server does BOTH and I had modelled only the first:
  // it drops the workspace root from writableRoots (workspaceWrite implies it, and it is reported under
  // runtimeWorkspaceRoots instead). Sending it anyway made assertWriteSandbox compare [cwd] against [] and
  // refuse a legitimate `--cwd X --writable X` with exit 4 — "codex crashed" for a redundant flag.
  roots = [...new Set(opts.writable.map((d) => checkRoot(resolveDir(d, "--writable"))))]
    .filter((r) => r !== cwd);
  if (opts.commit) {
    // The COMMON dir, not the per-worktree one. A narrower whitelist was measured and rejected: granting
    // {worktrees/<name>, objects, refs, logs/refs} does let add+commit through for a LINKED worktree on the
    // `files` ref backend, but `git branch -D` and `git tag -d` fail (packed-refs.lock is at the .git
    // root), `git gc` fails, every commit prints a packed-refs.lock error, and a reftable repo or a MAIN
    // worktree — where index.lock and COMMIT_EDITMSG live at the root — cannot be narrowed at all.
    // workspace-write has no deny-list, so "grant .git except hooks and config" is unexpressible here;
    // expressing it needs a permissions profile, which is a larger change than this flag.
    const r = spawnSync("git", ["-C", cwd, "rev-parse", "--path-format=absolute", "--git-common-dir"], { encoding: "utf8" });
    if (r.status !== 0) fail(EXIT.USAGE, "--commit needs a git repository at --cwd");
    const resolved = checkRoot(resolveDir(r.stdout.trim(), "the repository git directory"));
    // From a linked worktree the common dir is the MAIN clone's .git — config, hooks and every ref.
    // Granting it is sometimes necessary but never incidental, so say so out loud.
    process.stderr.write(`codex-delegate: --commit grants write access to ${resolved} (config, hooks, all refs)\n`);
    if (resolved !== cwd && !roots.includes(resolved)) roots.push(resolved);
  }

  if (opts.webSearch) {
    const allowed = managedWebSearchModes();
    if (allowed === undefined)
      fail(EXIT.USAGE, `this device has a managed Codex policy at ${MANAGED_PREFS} that could not be read, so whether --web-search ${opts.webSearch} is permitted cannot be established; the server would substitute a mode silently and no response field would say which`);
    if (allowed && !allowed.includes(opts.webSearch))
      fail(EXIT.USAGE, `--web-search ${opts.webSearch} is not permitted by this device's managed policy, which allows ${allowed.join("|")}; the server would silently apply one of those and no response field would say so`);
  }

  const config = [
    ["web_search", opts.webSearch ?? "disabled"],
    // A reader that cannot write $TMPDIR cannot start vitest at all (it mkdirs there before running).
    // Extending ":read-only" opens exactly that and nothing else — /tmp stays excluded.
    ...(opts.level === "read" ? [
      [`permissions.${READ_PROFILE}.extends`, '":read-only"'],
      [`permissions.${READ_PROFILE}.filesystem`, '{":tmpdir"="write"}'],
      ["default_permissions", `"${READ_PROFILE}"`]
    ] : []),
    // Omitted entirely when the caller did not name one, so ~/.codex/config.toml decides.
    ...(opts.effort ? [["model_reasoning_effort", opts.effort]] : []),
    // Sent UNCONDITIONALLY at write level, unlike --effort three lines up, and the difference is the
    // point: effort is a preference the caller may delegate to their config, whereas the sandbox is what
    // assertWriteSandbox then demands the server report back. Sending these only when a flag was given
    // left the flagless case to config.toml — so any `[sandbox_workspace_write]` in a user's config made
    // every write run fail that assert with exit 4, which reads as "codex crashed". The sandbox is a
    // function of the flags alone; that is what makes asserting it meaningful.
    ...(opts.level === "write" ? [
      ["sandbox_workspace_write.network_access", String(Boolean(opts.network))],
      ["sandbox_workspace_write.writable_roots", `[${roots.map((r) => JSON.stringify(r)).join(",")}]`]
    ] : []),
    // Per-run by construction: a grant riding the spawn args cannot leak into a concurrent run the
    // way one written into the shared isolated config could.
    ...(opts.mcp && mcpFromProbe ? mcpConfigEntries(mcpFromProbe) : [])
  ];
  spawnArgs = ["--strict-config", ...config.flatMap(([k, v]) => ["-c", `${k}=${v}`]), "app-server"];
}

// ---------------------------------------------------------------- transport

let child, settled = false, flushing = false;
// The config probe's own child, tracked at module scope so shutdown() can reach it. Held in a
// function-local it survived a SIGTERM aimed at the driver — the same way a review probe's background
// jobs outlived their run and burned eight cores for fifteen hours.
let probeChild = null;
// Set by inheritedConfig for its lifetime: the one way to end the probe that also settles its closure
// state, so a shutdown mid-probe does not trigger the probe's own close handler into a second group
// kill and a misleading "exited before replying" warning.
let probeCancel = null;
const pending = new Map();
let stderrBuf = "";
let stderrDropped = 0;
const STDERR_KEEP = 64 * 1024;
// A line the client cannot parse is a protocol fact, not noise. Failing the run on one is wrong — codex
// may print a banner one day — but discarding it silently means a malformed stream looks like a quiet one.
let unparsedLines = 0;

// detached:true gave the child its own process group, so the negative pid reaches its descendants
// too — killing only the app-server pid leaves orphaned test servers behind.
const killGroup = (sig) => { if (!child) return; try { process.kill(-child.pid, sig); } catch { try { child.kill(sig); } catch {} } };
// Signal 0 to the NEGATIVE pid answers "does any member of the group still exist" without touching it.
const groupAlive = () => { if (!child) return false; try { process.kill(-child.pid, 0); return true; } catch { return false; } };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Ends every child this driver started and WAITS for them, bounded: group SIGTERM, up to 2 s for the
// group to disappear, then SIGKILL and up to 1 s more. The predecessor of this function armed the same
// SIGKILL on an unref'd timer and then process.exit() discarded it, so a TERM-ignoring test server
// survived every normal completion and every timeout. The timers here are ref'd on purpose — an exiting
// driver must stay alive until the group is gone or the bound expires.
//
// The lock is released only AFTER that wait, so a next writer cannot enter the directory while this
// run's descendants are still dying in it. Idempotent: every caller shares one promise, and a repeat
// signal escalates the existing teardown instead of bypassing it.
let shutdownDone = null;
function shutdown() {
  if (shutdownDone) return shutdownDone;
  shutdownDone = (async () => {
    if (probeCancel) probeCancel();   // kills the group once and settles the probe's own state
    if (probeChild) {
      try { process.kill(-probeChild.pid, "SIGKILL"); } catch { try { probeChild.kill("SIGKILL"); } catch {} }
      probeChild = null;
    }
    if (child) {
      try { child.stdin.end(); } catch {}
      killGroup("SIGTERM");
      for (const end = Date.now() + 2000; groupAlive() && Date.now() < end; ) await sleep(50);
      if (groupAlive()) {
        killGroup("SIGKILL");
        for (const end = Date.now() + 1000; groupAlive() && Date.now() < end; ) await sleep(50);
      }
    }
    releaseLock();
  })();
  return shutdownDone;
}

function abort(code, msg) {
  if (settled) return;
  settled = true;
  process.stderr.write(`codex-delegate: ${msg}\n`);
  if (stderrBuf.trim()) {
    if (stderrDropped) process.stderr.write(`[${stderrDropped} earlier bytes of stderr dropped]\n`);
    process.stderr.write(`${stderrBuf.trim()}\n`);
  }
  process.exitCode = code;
  // The deadline can fire while still reading the prompt from stdin, before any child exists. Without
  // this the process announces its own timeout and then blocks on stdin forever.
  if (!child) { try { process.stdin.destroy(); } catch {} }
  shutdown();
}

function rejectAllPending(err) {
  for (const p of pending.values()) p.reject(err);
  pending.clear();
}

// ---------------------------------------------------------------- state

let rootThreadId = null, rootTurnId = null;
// An inline review can attribute its items to the reviewThreadId the response names; events on it are
// OURS. Aliases extend attribution, never replace the root id the report and receipt are keyed on.
const rootAliases = new Set();
let reviewResult = null;    // the exitedReviewMode payload — the review itself
const commands = [];        // root-thread commandExecution items only
const messages = [];        // root-thread agentMessage items only
const fileChanges = [];     // root-thread fileChange items: what the turn actually wrote
const escalations = [];     // refused permission requests — the sandbox was sized too small
const interactions = [];    // requests that needed a human: no sandbox change can answer them
const reasoningSummaries = [];  // root-thread reasoning item summaries — the inspectable thinking a Claude subagent's transcript has
const otherItemCounts = {}; // root-thread item types the evidence gates ignore (mcpToolCall, webSearch, plan, …), counted so the report does not silently drop them
const subagentThreads = new Map();  // threads the server started under ours: id -> {items, commands}
let turnStatus = null;
let turnError = null;
let selectedModel = null;   // what the server resolved, which may not be what was asked for
let selectedEffort = null;  // likewise: with no --effort this is whatever config.toml chose
let effectiveSandbox = null;   // the sandbox the SERVER applied, not the one we asked for
let verifyResult = null;    // the caller-run check, the one piece of evidence the model cannot author
let tokenUsage = null;      // the latest thread/tokenUsage/updated payload: what this seat cost
let outputAttempts = 0;     // turns STARTED under --output-schema; at most one corrective retry
let requestFn = null;       // main()'s request closure, hoisted so the corrective turn can reach it
let lastTurnParams = null;  // the original turn/start params, so a transient retry replays them exactly
const transientRetries = [];  // {cause, delayMs} per retry taken, for the report
// Every turn id OUR turn/start calls returned. Evidence attribution checks membership here rather than
// equality with the latest id: a first-turn item that raced past its own turn/completed used to be
// replayed under the corrective turn's id and dropped, contradicting "the first turn's evidence stays
// counted". A resumed thread's PRIOR turns are still excluded — their ids never came from us.
const ownedTurns = new Set();

// Fail CLOSED on BOTH ids. Thread alone is not enough: a stale item from an earlier turn on the same
// thread, or a completion delivered before the turn/start response, would otherwise be accepted as ours.
// Notifications carry turnId as a required field; use it.
// The turn id does not live in the same place for every message: ItemCompletedNotification carries a
// required top-level `turnId`, while TurnCompletedNotification carries only `threadId` and `turn`.
// Reading `turnId` for both silently rejects every real completion.
const turnIdOf = (p) => p?.turnId ?? p?.turn?.id ?? null;
const isRoot = (p) =>
  rootThreadId !== null &&
  ((p?.threadId ?? null) === rootThreadId || rootAliases.has(p?.threadId ?? "")) &&
  turnIdOf(p) !== null && ownedTurns.has(turnIdOf(p));

// Events can share a stdout chunk with the turn/start response and so arrive before rootTurnId is known.
// Holding them keyed by their own turnId lets the right ones be replayed once the id is established,
// instead of being either dropped or waved through.
const early = [];
function replayEarly() {
  const held = early.splice(0, early.length);
  // Completion last, whatever order it arrived in: replaying it first would call finish() before the
  // items it summarises had been counted, and the turn would report as empty.
  const terminal = (m) => m.method === "turn/completed";
  for (const m of held.filter((m) => !terminal(m))) handleMessage(m);
  for (const m of held.filter(terminal)) handleMessage(m);
}

function handleServerRequest(msg) {
  const send = (result) => child.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", id: msg.id, result })}\n`);
  const sendError = (message) => child.stdin.write(
    `${JSON.stringify({ jsonrpc: "2.0", id: msg.id, error: { code: -32601, message } })}\n`
  );
  // Attribution for REQUESTS must fail closed, and cannot demand ids the schema does not always carry:
  // MCP elicitation has a nullable turnId, and attestation and token refresh carry no ids at all. So a
  // request counts as ours unless it positively proves it belongs to another thread.
  // The legacy applyPatch/execCommand pair identifies its conversation with `conversationId`, not
  // `threadId`; checking only the latter attributed another thread's refusal to us.
  const owner = msg.params?.threadId ?? msg.params?.conversationId ?? null;
  const foreign = rootThreadId !== null && owner != null && owner !== rootThreadId;

  // Refusal shapes differ per method; they are taken from the pinned schema-<version>/*ApprovalResponse.json.
  // `decline` is only valid for the two item/* approvals — the legacy pair accepts abort|allow|approved,
  // and the permissions request answers with a granted profile rather than a decision at all.
  const REFUSALS = {
    "item/commandExecution/requestApproval": { decision: "decline" },
    "item/fileChange/requestApproval": { decision: "decline" },
    "applyPatchApproval": { decision: "abort" },
    "execCommandApproval": { decision: "abort" },
    "item/permissions/requestApproval": { permissions: { fileSystem: null, network: null } },
  };
  // An MCP form is a request for a human, not for a wider sandbox — declining it is valid, but
  // classifying it as "the sandbox was too small" would send the caller to fix the wrong thing.
  if (msg.method === "mcpServer/elicitation/request") {
    if (!foreign) interactions.push(msg.method);
    send({ action: "decline" });
    return;
  }

  const refusal = REFUSALS[msg.method];
  if (refusal) {
    // Granting here would let Codex step outside the sandbox the caller chose — that is the caller's
    // call, not this driver's. Always refuse; count it against OUR sandbox unless the request proves it
    // belongs to another thread, so a request carrying no ids at all still fails closed.
    // Recorded whichever thread asked. The root-only filter elsewhere exists so a CHILD's command cannot
    // satisfy the gate — that is evidence of success, and evidence of success must be strict. An
    // escalation is evidence of FAILURE, and that must be inclusive: the refusal below is sent
    // unconditionally, so a subagent really was blocked, and reporting a clean run would hide it.
    const detail = String(msg.params?.command ?? msg.params?.reason ?? msg.params?.message ?? "").slice(0, 200);
    escalations.push({ method: msg.method, detail, thread: owner, subagent: foreign });
    send(refusal);
    return;
  }

  // Attestation, ChatGPT token refresh, and anything a later version adds. These are not escalations
  // and must not be reported as one; an approval-shaped result would be invalid, so answer with an
  // honest JSON-RPC error.
  if (!foreign) interactions.push(msg.method);
  sendError(`${msg.method} is not supported by codex-delegate`);
}

function handleMessage(msg) {
  if (msg.id !== undefined && !msg.method) {
    const p = pending.get(msg.id);
    if (!p) return;
    pending.delete(msg.id);
    // Assign the root ids HERE, synchronously, not in the await continuation. readline dispatches every
    // line of one stdout chunk in a single synchronous burst, so notifications sharing a chunk with this
    // response would otherwise be handled while the id is still null — and the filters would let a
    // foreign thread's events through.
    if (msg.result && (p.method === "thread/start" || p.method === "thread/resume")) {
      rootThreadId = msg.result.thread?.id ?? null;
      selectedModel = msg.result.model ?? null;
      selectedEffort = msg.result.reasoningEffort ?? null;
    }
    if (msg.result && (p.method === "turn/start" || p.method === "review/start")) {
      rootTurnId = msg.result.turn?.id ?? null;
      if (rootTurnId !== null) ownedTurns.add(rootTurnId);
      if (p.method === "review/start" && typeof msg.result.reviewThreadId === "string"
          && msg.result.reviewThreadId !== rootThreadId)
        rootAliases.add(msg.result.reviewThreadId);
      replayEarly();          // anything that shared this chunk can now be attributed
    }
    if (msg.error) {
      // -32601 means the server does not know a method this driver sends, which after a codex upgrade is
      // the single most likely failure — and as a raw JSON blob under a generic transport error it reads
      // as a crash rather than as protocol drift. Name it and say what to do.
      const e = new Error(msg.error.code === -32601
        ? `the server does not support ${p.method} (JSON-RPC -32601): your codex and this plugin have ` +
          `drifted apart. Update the plugin, or pin codex to the version it was measured against ` +
          `(schema-<version>/ in the plugin root names it).`
        : `${p.method}: ${JSON.stringify(msg.error)}`);
      e.rpcCode = msg.error.code;
      p.reject(e);
    } else p.resolve(msg.result);
    return;
  }
  if (msg.id !== undefined && msg.method) return handleServerRequest(msg);

  const p = msg.params;

  // Turn-scoped notifications that arrive before the turn id is known are held, not judged.
  const turnScoped = msg.method === "item/completed" || msg.method === "turn/completed";
  if (turnScoped && rootTurnId === null) { early.push(msg); return; }

  // Live progress, opt-in: one line per item START, so a coordinator tailing a long seat sees the
  // phase it is in — without re-enabling the delta firehose, which stays opted out. Best-effort: an
  // item racing the turn/start response is simply not announced.
  if (opts.progress && msg.method === "item/started" && isRoot(p)) {
    const it = p.item;
    const line = it?.type === "commandExecution" ? `run: ${String(it.command ?? "").slice(0, 120)}`
      : it?.type === "fileChange" ? `edit: ${(it.changes ?? []).map((c) => c.path).join(", ").slice(0, 120)}`
      : it?.type === "webSearch" ? `search: ${String(it.query ?? "").slice(0, 120)}`
      : null;
    if (line) process.stderr.write(`codex-delegate: > ${line}\n`);
  }

  // A subagent thread the server started under ours: registered so its activity is visible in the
  // report rather than invisibly filtered. Evidence attribution stays root-only — a child's command is
  // never proof of OUR work — but a coordinator deserves to know the children existed and how busy
  // they were.
  if (msg.method === "thread/started" && p?.thread?.parentThreadId && rootThreadId !== null
      && p.thread.parentThreadId === rootThreadId)
    subagentThreads.set(p.thread.id, { items: 0, commands: 0 });
  if (msg.method === "item/completed" && subagentThreads.has(p?.threadId ?? "")) {
    const t = subagentThreads.get(p.threadId);
    t.items++;
    if (p.item?.type === "commandExecution") t.commands++;
  }

  if (msg.method === "item/completed" && isRoot(p)) {
    const it = p.item;
    if (it?.type === "commandExecution") commands.push({ command: String(it.command), exitCode: it.exitCode, status: it.status });
    if (it?.type === "agentMessage" && it.text) messages.push({ text: it.text, phase: it.phase ?? null, turnId: turnIdOf(p) });
    // The summary is the same artefact a Claude subagent's transcript exposes as its thinking; bounded,
    // because reasoning can be long and the report is not the place for a novel.
    if (it?.type === "reasoning") {
      const s = Array.isArray(it.summary) ? it.summary.join("\n") : String(it.summary ?? "");
      if (s.trim() && reasoningSummaries.length < 40) reasoningSummaries.push(s.slice(0, 2000));
    }
    // The review itself, under --review: the server hands it back as the exitedReviewMode item.
    if (it?.type === "exitedReviewMode" && it.review != null) reviewResult = it.review;
    // Everything else — mcpToolCall, webSearch, plan, collabAgentToolCall, whatever a later server
    // adds — is counted by type: the report used to drop these on the floor, so a turn that mostly
    // searched or called tools looked idle.
    if (it?.type && !["commandExecution", "agentMessage", "fileChange", "reasoning"].includes(it.type))
      otherItemCounts[it.type] = (otherItemCounts[it.type] ?? 0) + 1;
    // A write-level run said nothing about what it WROTE. The schema carries it — FileChangeThreadItem
    // requires {changes:[{path,kind,diff}], status}, and PatchApplyStatus includes failed and declined —
    // so a patch that failed for a reason other than a refused approval was invisible in both the report
    // and the exit code. Same hole the command list already closed.
    if (it?.type === "fileChange") {
      for (const ch of it.changes ?? [])
        // PatchChangeKind is a oneOf of OBJECTS ({type:"add"} / {type:"delete"} / {type:"update",move_path}),
        // not a string. Storing it raw rendered every write run's blast-radius line as "[object Object]",
        // and the fixture had invented the string form — the third time a made-up shape in that file made
        // the suite green against something the server never sends.
        // move_path is the destination of a rename, and dropping it made the report state a falsehood
        // silently: filesTouched named the path that no longer exists and omitted the one that does, so a
        // coordinator harvesting the change set read a deleted file and never learned of the new one.
        fileChanges.push({ path: String(ch.path), kind: ch.kind?.type ?? String(ch.kind),
                           move: ch.kind?.move_path ?? null, status: it.status });
    }
  }
  // Best-effort accounting: what this seat cost, straight from the server. Only the root thread's
  // usage counts — a subagent thread's tokens are its own. `total` is THREAD-cumulative: on --resume
  // it includes every earlier invocation's turns; `last` is the most recent turn alone.
  if (msg.method === "thread/tokenUsage/updated" && rootThreadId !== null && (p?.threadId ?? null) === rootThreadId)
    tokenUsage = p?.tokenUsage ?? null;

  // A subagent finishing its own turn, or an earlier turn on our own thread, must not end ours.
  // The settled guard matters here specifically: after a timeout has already reported, a completion
  // still in the pipe used to overwrite turnStatus and could START a corrective turn on a run that had
  // just declared itself dead — a real server-side turn, killed moments later by the teardown.
  if (msg.method === "turn/completed" && isRoot(p)) {
    if (settled) return;
    turnStatus = p?.turn?.status ?? "unknown";
    // Populated only when the turn failed, and it carries an enumerated cause worth acting on:
    // usageLimitExceeded / serverOverloaded / responseStreamDisconnected -> retried below, once;
    // contextWindowExceeded -> the handoff was too large, split it; unauthorized -> stop;
    // sandboxError -> the rights level was wrong.
    turnError = p?.turn?.error ?? null;
    // The comment above always KNEW which causes are transient; nothing acted on it, so a provider
    // blip failed the whole delegation. ONE bounded retry, and only while the turn produced nothing
    // observable — no commands, no file changes, no messages — because replaying the prompt after
    // visible work risks doing that work twice. The wall clock must leave the backoff plus at least
    // ten seconds of turn, or the retry just converts a failure into a timeout.
    if (turnStatus === "failed" && transientRetries.length === 0 && lastTurnParams !== null
        && RETRYABLE[errKind(turnError)] !== undefined
        && commands.length === 0 && fileChanges.length === 0 && messages.length === 0
        && startedAtMs + opts.timeout * 1000 - Date.now() > RETRYABLE[errKind(turnError)] + 10000) {
      startTransientRetry(errKind(turnError));
      return;
    }
    // Under --output-schema a completed turn whose answer misses the shape gets ONE corrective turn on
    // the same thread — the validation errors and nothing else — mirroring the retry a Claude
    // subagent's tool layer provides. The commands and evidence of the first turn stay counted.
    // outputAttempts counts turns STARTED (set in main and in startCorrectiveTurn), so a corrective
    // turn cut off by the deadline is still an attempt the report admits to.
    if (opts.outputSchema && turnStatus === "completed") {
      const errs = answerSchemaErrors(currentFinalAnswer());
      if (errs.length && outputAttempts < 2) { startCorrectiveTurn(errs); return; }
    }
    finish();
  }
}

// The final-answer selection, shared by finish() and the schema-retry decision above so the two can
// never disagree about which message is the answer. Judged PER TURN, newest turn first: the schema
// permits phase null, and a corrective turn whose valid answer arrived unphased used to lose to the
// first turn's phased prose — the retry's whole product discarded by a tie-break across turns.
function currentFinalMsg() {
  const pick = (ms) => {
    const nonBlank = ms.filter((m) => String(m.text).trim());
    const phased = nonBlank.filter((m) => m.phase === "final_answer");
    return phased.at(-1) ?? (nonBlank.every((m) => m.phase == null) ? nonBlank.at(-1) ?? null : null);
  };
  const turns = [...new Set(messages.map((m) => m.turnId))];
  for (let i = turns.length - 1; i >= 0; i--) {
    const found = pick(messages.filter((m) => m.turnId === turns[i]));
    if (found) return found;
  }
  return null;
}
const currentFinalAnswer = () => currentFinalMsg()?.text ?? "";

// A deliberately SHALLOW validator — type, required, properties, enum, items — not a JSON Schema
// implementation. The server already constrains generation with the full schema; this is the driver's
// independent check of the load-bearing subset, kept small enough to trust without a dependency.
// Unknown keywords are ignored, which fails OPEN for exotic schemas: say so rather than pretend.
function schemaErrors(value, schema, at = "$") {
  const errs = [];
  const typeOf = (v) => Array.isArray(v) ? "array" : v === null ? "null" : typeof v;
  const t = schema?.type;
  if (t !== undefined) {
    const types = Array.isArray(t) ? t : [t];
    const vt = typeOf(value);
    const ok = types.includes(vt) || (vt === "number" && types.includes("integer") && Number.isInteger(value));
    if (!ok) { errs.push(`${at}: expected ${types.join("|")}, got ${vt}`); return errs; }
  }
  // Structural equality, not stringify: object-valued enum members serialised with reordered keys used
  // to burn the corrective turn and exit 13 on a compliant answer.
  if (Array.isArray(schema?.enum) && !schema.enum.some((e) => deepEqual(e, value)))
    errs.push(`${at}: not one of the permitted values`);
  if (typeOf(value) === "object") {
    // hasOwn, not `in`: JSON.parse objects inherit Object.prototype, so required:["toString"] was
    // satisfied by every object.
    for (const k of schema?.required ?? []) if (!Object.hasOwn(value, k)) errs.push(`${at}.${k}: required and missing`);
    // hasOwn here too, and for the mirror-image reason. `k in value` reaches the PROTOTYPE, so a schema
    // with an optional property named after anything on Object.prototype validated the inherited member
    // instead of the absent one — measured: schema {"properties":{"toString":{"type":"string"}}} against
    // the compliant answer {"verdict":"ok"} produced `$.toString: expected string, got function`, burned
    // the corrective turn and exited 13 on an answer that matched. The line above already knew this.
    for (const [k, sub] of Object.entries(schema?.properties ?? {})) if (Object.hasOwn(value, k)) errs.push(...schemaErrors(value[k], sub, `${at}.${k}`));
    // The strict schema the server demands says no extra keys; check it here too rather than declaring
    // it unchecked, so outputSchemaOk means the same thing the server enforced.
    if (schema?.additionalProperties === false) {
      const known = new Set(Object.keys(schema?.properties ?? {}));
      for (const k of Object.keys(value)) if (!known.has(k)) errs.push(`${at}.${k}: not permitted by the schema (additionalProperties is false)`);
    }
  }
  if (typeOf(value) === "array" && schema?.items && !Array.isArray(schema.items))
    value.forEach((v, i) => errs.push(...schemaErrors(v, schema.items, `${at}[${i}]`)));
  return errs;
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every((k) => Object.hasOwn(b, k) && deepEqual(a[k], b[k]));
}

function answerSchemaErrors(text) {
  const parsed = parseAnswerJson(text);
  // A literal `null` answer is VALID JSON, so it must not be diagnosed as a parse failure. It used to
  // be: answerJson null with answerJsonError null took the first branch and reported "the answer is not
  // valid JSON: null", which then went into the corrective turn's prompt as the thing to fix — sending
  // the model after a syntax error it did not make, and leaving the branch below unable to ever see a
  // JSON null. The two states are told apart by the error field, not by the value.
  if (parsed.answerJson === null && parsed.answerJsonError !== null)
    return [`the answer is not valid JSON: ${parsed.answerJsonError}`];
  // The contract is one bare OBJECT, independent of how lax the schema is: an array, a scalar or null
  // parses as JSON but is never an acceptable answer shape.
  if (parsed.answerJson === null || typeof parsed.answerJson !== "object" || Array.isArray(parsed.answerJson))
    return ["the answer is valid JSON but not an object"];
  return schemaErrors(parsed.answerJson, opts.outputSchema);
}

// The backoff per transient cause. A disconnected stream is ready again almost at once; an overloaded
// server and an exceeded usage window deserve a real pause.
const RETRYABLE = { responseStreamDisconnected: 2000, serverOverloaded: 10000, usageLimitExceeded: 10000 };
function startTransientRetry(cause) {
  const delayMs = RETRYABLE[cause];
  transientRetries.push({ cause, delayMs });
  process.stderr.write(`codex-delegate: turn failed with ${cause}; retrying once in ${delayMs / 1000}s\n`);
  // Hold the new turn's events until its id arrives, exactly as at startup and in the corrective turn.
  rootTurnId = null;
  // Ref'd on purpose: the timer must fire even if every pipe momentarily goes quiet.
  setTimeout(() => {
    if (settled) return;
    requestFn("turn/start", lastTurnParams).catch((e) => {
      if (settled) return;
      process.stderr.write(`codex-delegate: the retry failed to start (${e.message}); reporting the original failure\n`);
      turnStatus = "failed";
      finish();
    });
  }, delayMs);
}

function startCorrectiveTurn(errs) {
  // Hold the new turn's events until its id arrives, exactly as at startup — without this, an item
  // racing the turn/start response would be judged against the OLD turn id and dropped.
  rootTurnId = null;
  outputAttempts++;
  process.stderr.write(`codex-delegate: the answer failed schema validation (${errs.length} error(s)); spending the corrective turn\n`);
  requestFn("turn/start", {
    threadId: rootThreadId,
    input: [{ type: "text", text:
      `Your final answer did not match the required JSON schema. Errors:\n- ${errs.slice(0, 8).join("\n- ")}\n` +
      "Reply again with ONE corrected JSON object and nothing else — no prose before or after, no code fence.",
      text_elements: [] }],
    model: opts.model ?? null, effort: null, outputSchema: opts.outputSchema
  }).catch((e) => {
    // The FIRST turn completed and its evidence is all in memory; aborting here threw the whole report
    // away and exited 4 for a turn/start refusal. Finish instead: the report carries the first answer,
    // its schemaErrors and exit 13 — plus the refusal on stderr for the record.
    if (settled) return;
    process.stderr.write(`codex-delegate: the corrective turn failed to start (${e.message}); reporting the first attempt\n`);
    turnStatus = "completed";
    finish();
  });
}

// A Claude subagent can be handed a schema and the tool layer retries until the shape matches. There is no
// such layer here, so --answer-json asks for the shape and then reports honestly whether it arrived: a
// caller that machine-reads the answer must be able to tell a parse failure from a null field. The fence
// strip is not politeness — instructed or not, a fenced block is the single most common way the answer
// comes back unparseable, and treating it as a failure would throw away a good answer.
function parseAnswerJson(text) {
  if (typeof text !== "string" || text.trim() === "") return { answerJson: null, answerJsonError: "no answer" };
  const fenced = text.trim().match(/^```(?:json)?\s*\n([\s\S]*?)\n```$/);
  const body = fenced ? fenced[1] : text.trim();
  try { return { answerJson: JSON.parse(body), answerJsonError: null }; }
  catch (e) { return { answerJson: null, answerJsonError: e.message }; }
}

// The rollout under ~/.codex/sessions carries the originator, the model provider and the whole turn —
// the receipt a wrapper cannot forge. Today's and yesterday's date directories are checked, because a
// turn can cross midnight; a resumed thread older than that reports null, which means "not found in the
// last two days", not "fabricated". A present receipt proves the turn ran; judge absence carefully.
//
// The file is OPENED and its first record read, not merely matched by name. Matching a filename is
// exactly as strong as `touch rollout-<any id>.jsonl`, which is to say not strong at all, and the field
// it fed was published as proof the turn really ran. The first record is `session_meta` and carries the
// session id, the originator and the model provider, so verification costs one bounded read and turns
// receiptOk from "a file with this name exists" into "a session record claiming this thread exists".
// Those three values are surfaced too: a coordinator checking a seat wants to see `"Claude Code"` and
// `"openai"`, not to be told that a path was found.
//
// $CODEX_DELEGATE_SESSIONS_DIR moves the search root, and exists so this can be TESTED. Before it there
// was no positive case at all — the one receipt case asserted receiptOk:false, and replacing the whole
// function with `return null` left every suite green, which is a strange state for the field the README
// calls proof the turn really ran. It weakens nothing: a process that can set this variable is already
// the process that writes the report, and could fabricate every field in it.
const RECEIPT_HEAD_BYTES = 64 * 1024;
function findRollout(threadId) {
  if (!threadId) return null;
  try {
    const base = process.env.CODEX_DELEGATE_SESSIONS_DIR
      || path.join(os.userInfo().homedir, ".codex", "sessions");
    for (let back = 0; back < 2; back++) {
      const d = new Date(Date.now() - back * 86400000);
      const dir = path.join(base, String(d.getFullYear()),
        String(d.getMonth() + 1).padStart(2, "0"), String(d.getDate()).padStart(2, "0"));
      let names;
      try { names = fs.readdirSync(dir); } catch { continue; }
      const hit = names.find((n) => n.startsWith("rollout-") && n.includes(threadId));
      if (!hit) continue;
      const p = path.join(dir, hit);
      const res = { path: p, verified: false, originator: null, modelProvider: null, cwd: null,
                    why: "the first record could not be read" };
      // Bounded, and only the first line: a rollout of a long turn is megabytes, and everything this
      // needs is in its opening record.
      let head = "";
      try {
        const fd = fs.openSync(p, "r");
        try {
          const buf = Buffer.alloc(RECEIPT_HEAD_BYTES);
          head = buf.subarray(0, fs.readSync(fd, buf, 0, RECEIPT_HEAD_BYTES, 0)).toString("utf8");
        } finally { fs.closeSync(fd); }
      } catch (e) { res.why = `the rollout could not be opened (${e.code ?? e.message})`; return res; }
      const firstLine = head.split("\n")[0] ?? "";
      let meta = null;
      try { meta = JSON.parse(firstLine); } catch { res.why = "the first record is not JSON"; return res; }
      const pay = meta?.payload ?? {};
      const id = pay.id ?? pay.session_id ?? null;
      if (meta?.type !== "session_meta") { res.why = `the first record is ${JSON.stringify(meta?.type ?? null)}, not session_meta`; return res; }
      if (id !== threadId) { res.why = `the rollout's session id is ${JSON.stringify(id)}, not this thread`; return res; }
      res.verified = true;
      res.why = null;
      res.originator = typeof pay.originator === "string" ? pay.originator : null;
      res.modelProvider = typeof pay.model_provider === "string" ? pay.model_provider : null;
      res.cwd = typeof pay.cwd === "string" ? pay.cwd : null;
      return res;
    }
  } catch {}
  return null;
}

// `reason` is set when the run is being cut short (a timeout) rather than ending on its own. Everything
// streamed so far is still in memory, and a run that did four useful greps before the clock ran out
// should hand those back rather than throw them away.
// codexErrorInfo is either a bare string or a one-key tagged object; reading .type gives "unknown".
// Written beside nothing in particular, on purpose: the rollout under ~/.codex/sessions is the server's
// record of the turn, and this is the driver's record of what it handed back. Failing to write one is not
// worth failing a finished turn over, so a write error costs the path and nothing else.
function persistAnswer(text) {
  if (!text) return null;
  try {
    // Inside the try, and this is the whole point of the function's contract. passwdHome() does not
    // return an error, it calls fail(), which sets the exit code and throws — so with this line outside,
    // a uid with no passwd entry turned "the answer log could not be written" into an exception raised
    // while building the report of a turn that had already succeeded. Measured: the process stayed alive
    // through four of its own timeout periods rather than exiting.
    // os.userInfo() directly, NOT passwdHome(): that helper reports a missing passwd entry through fail(),
    // which prints a refusal and sets the exit code. Inside a best-effort side write on a turn that had
    // already succeeded, that printed "codex-delegate: cannot resolve your home directory" to stderr and
    // then exited 0 — a refusal and a success in the same run.
    const dir = answersDir();
    const name = `${rootThreadId ?? `no-thread-${process.pid}`}.md`;
    fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    fs.writeFileSync(path.join(dir, name), text, { mode: 0o600 });
    pruneAnswers(dir);
    return path.join(dir, name);
  } catch { return null; }
}

// Bounded retention for the answer log, which used to grow without bound. Fourteen days and four
// hundred entries are both far past any live coordinator's reach-back; the newest file — the one this
// very run just wrote — is never eligible.
function pruneAnswers(dir) {
  try {
    const now = Date.now();
    const entries = fs.readdirSync(dir)
      .map((n) => { try { return { n, t: fs.statSync(path.join(dir, n)).mtimeMs }; } catch { return null; } })
      .filter(Boolean).sort((a, b) => b.t - a.t);
    for (const [i, e] of entries.entries())
      if (i > 0 && (now - e.t > 14 * 86400000 || i >= 400)) fs.rmSync(path.join(dir, e.n), { force: true });
  } catch {}
}

// Cuts on a line boundary and says where the rest is, because an answer that stops mid-sentence with no
// forwarding address is worse than a long one.
function clip(text, maxLines, maxBytes, where) {
  const lines = text.split("\n");
  let out = lines.length > maxLines ? lines.slice(0, maxLines).join("\n") : text;
  const marker = (body) => `${body}\n\n[clipped: ${lines.length} lines, ${Buffer.byteLength(text, "utf8")} bytes${where ? ` — full answer at ${where}` : ""}]`;
  // Bytes, not UTF-16 units. `.length` counts the latter, so a cyrillic or emoji answer sailed past a
  // 4000-"byte" cap at 8003 actual bytes — the cap exists to bound what lands in a coordinator's context,
  // and that is measured in bytes.
  // The marker is counted INSIDE the cap, not appended after it. It used to be added afterwards, so the
  // one number the flag promises was always exceeded by the length of the sentence explaining that it
  // had not been — a small lie, in the field whose entire job is to be a bound.
  const ELLIPSIS = "…";
  const budget = Math.max(0, maxBytes - Buffer.byteLength(marker(""), "utf8") - Buffer.byteLength(ELLIPSIS, "utf8"));
  if (Buffer.byteLength(out, "utf8") > budget) {
    out = Buffer.from(out, "utf8").subarray(0, budget).toString("utf8").replace(/�$/, "") + ELLIPSIS;
  }
  if (out === text) return text;
  return marker(out);
}

// The server nests the upstream API error as a JSON STRING inside turnError.message, so the useful part —
// which parameter, and what it would have accepted — is invisible to a caller reading errKind alone.
function invalidRequest(e) {
  // The server has two ways to say it: an enumerated codexErrorInfo, and the upstream API error nested as
  // a JSON string. Only the second was checked, so a schema-native `badRequest` came back as exit 1 —
  // "the turn died, retry" — for something the caller had to change.
  if (e?.codexErrorInfo === "badRequest") return true;
  try { return JSON.parse(e?.message ?? "")?.error?.type === "invalid_request_error"; }
  catch { return false; }
}

// Printing turnError.message raw puts a pretty-printed JSON blob in the footer, so the one sentence that
// says which parameter was wrong scrolls past behind punctuation. Unwrap it when it is there.
function errText(e) {
  const raw = e?.message ?? "";
  try {
    const inner = JSON.parse(raw)?.error;
    if (inner?.message) return `${inner.message}${inner.param ? ` (param: ${inner.param})` : ""}`;
  } catch { /* not the nested shape; the raw text is the best there is */ }
  return raw;
}

function errKind(e) {
  const i = e?.codexErrorInfo ?? e?.type;
  if (typeof i === "string") return i;
  if (i && typeof i === "object") return Object.keys(i)[0] ?? "unknown";
  return "unknown";
}

// Ask the server to end the turn cleanly before the group is torn down. Without this a cancelled or
// timed-out seat's turn died WITH the process: the rollout never recorded an interruption and the
// thread was not reliably idle, so --resume on a cancelled seat was a gamble. Fire-and-forget — the
// report must not wait on a server that may be the reason we are cancelling; shutdown()'s stdin.end
// flushes the write, and the SIGTERM grace gives the server time to act on it.
function interruptTurn() {
  const turnId = rootTurnId ?? [...ownedTurns].at(-1) ?? null;
  if (!child || !rootThreadId || !requestFn || turnId === null) return;
  try { requestFn("turn/interrupt", { threadId: rootThreadId, turnId }).catch(() => {}); } catch {}
}

function finish(reason) {
  if (settled) return;
  settled = true;
  if (reason) turnStatus = reason;

  // A command that merely produced a number is not evidence: `false` exits 1 and would have passed.
  // Require a command that actually succeeded.
  const ran = commands.filter((c) => c.status === "completed" && c.exitCode === 0);
  // The schema's CommandExecutionStatus is {inProgress, completed, failed, declined} and exitCode may be
  // null, so a command can FAIL while carrying no numeric code at all. Keying the failure set on the code
  // alone put those in `blocked`, which the footer prints but the exit ladder ignores — the report said
  // "NEVER RAN pnpm test" while the run exited 0 under an answer claiming the tests passed.
  const verdictFailed = (c) => c.status === "failed" || c.status === "declined";
  const blocked = commands.filter((c) => !verdictFailed(c) && typeof c.exitCode !== "number");
  // A probe whose exit code answers a QUESTION is not a failed command: grep/rg exit 1 for "no match",
  // test/[ for "false", diff/cmp for "the files differ" — each reserves 2 for real trouble. Counting
  // them as failures made a routine research seat exit 11 for a grep that found nothing — measured,
  // 7 of 26 read seats in one audit session. Exit 1 EXACTLY, and only a PLAIN probe command: a pipe,
  // a compound or a substitution keeps failure semantics, because its exit 1 may be someone else's.
  // `declined` is an approval refusal whatever the code says, and never a probe answer.
  const PROBE_RE = /^\s*(?:grep|rg|egrep|fgrep|test|\[|diff|cmp|git\s+(?:diff|grep))(?:\s[^|&;`$]*)?$/;
  const probeNegative = (c) => c.status !== "declined" && c.exitCode === 1 && PROBE_RE.test(String(c.command));
  const probeNegatives = commands.filter(probeNegative);
  // A command that ran and FAILED belongs to neither set, so it was printed nowhere — while the footer
  // told the reader to check the list. A suite that ran and failed under a final answer claiming it
  // passed is exactly the case this report exists to expose.
  const failedCmds = commands.filter((c) => !probeNegative(c) && (verdictFailed(c) || (typeof c.exitCode === "number" && c.exitCode !== 0)));
  // A patch that could not be applied is the same class of fact as a command that failed, and was counted
  // nowhere: PatchApplyStatus has failed and declined, and neither reached the ladder.
  const failedPatches = fileChanges.filter(verdictFailed);
  // Events can only show that SOMETHING succeeded, never that the right thing did — Codex opens most
  // turns by reading its own skill files, and that alone satisfies any generic gate. --expect-command
  // is the caller declaring what the evidence must look like.
  const expected = opts.expectRe ? ran.filter((c) => opts.expectRe.test(c.command)) : ran;
  // Only a final_answer counts. Falling back to the last message of any phase turns the model's
  // thinking-out-loud into the deliverable, and the run reports success on commentary.
  // The schema permits phase: null, and older servers omit it. Prefer an explicit final_answer; fall back
  // to the last non-blank unphased message only when nothing was phased at all.
  const final = currentFinalMsg();
  // Under --review the deliverable is the review payload, not an agentMessage; a message still wins
  // when the server sends one.
  const fullAnswer = final?.text
    ?? (reviewResult != null ? (typeof reviewResult === "string" ? reviewResult : JSON.stringify(reviewResult, null, 2)) : "");
  // Recomputed here rather than trusted from the retry path: a timeout or failed turn never reached
  // that path, and the verdict must describe the answer this report actually carries.
  const schemaErrs = opts.outputSchema && fullAnswer ? answerSchemaErrors(fullAnswer) : opts.outputSchema ? ["no answer arrived"] : null;
  const answerPath = persistAnswer(fullAnswer);
  // Capped only when asked. A caller who did not ask for --brief gets exactly what the model said, because
  // silently truncating an answer is how a coordinator ends up acting on half a sentence.
  const answer = opts.brief ? clip(fullAnswer, BRIEF_LINES, BRIEF_BYTES, answerPath) : fullAnswer;
  const commentaryOnly = !final && reviewResult == null && messages.length > 0;

  // --verify runs on its OWN schedule, not as a reward for having passed the weaker gates. It used to be
  // gated on the ladder already reading 0, which inverted the evidence: --expect-command greps command
  // strings the MODEL wrote and is defeated by `true # vitest`, while --verify is a command the CALLER
  // runs afterwards and cannot be authored by the model. The weak check was cancelling the strong one, and
  // the report said `verify: null` — so a proven-broken end state and a proven-good one printed alike.
  //
  // Skipped on a timeout only, and for a reason: the deadline fires while Codex is still alive and
  // possibly mid-write, so the check would read a torn tree. verifySkipped records which it was, because
  // "not measured" and "not requested" are different facts about the run.
  let verifySkipped = opts.verify ? null : "not-requested";
  if (opts.verify) {
    if (turnStatus === "timedOut") verifySkipped = "turn-timed-out";
    else if (turnStatus !== "completed") verifySkipped = `turn-${turnStatus}`;
    else {
      // The budget is the caller's, not a private 300s: a --timeout 5 run must not spend 300s in here.
      // killSignal matters as much as the timeout — spawnSync's default SIGTERM is ignorable, so a
      // verifier that traps it ran to completion and was still reported as timed out.
      // maxBuffer: the default 1MB kills a verifier that prints a lot and reports status null / ENOBUFS,
      // turning a passing check into a failure.
      // Bounded by what is LEFT of the caller's wall clock, with no floor: the old 1 s minimum let a
      // completion arriving just before the deadline buy the verifier a second past the budget.
      const remainingMs = startedAtMs + opts.timeout * 1000 - Date.now();
      // The floor is overridable so this branch can be REACHED by a test. Hitting it by timing means
      // landing the turn's completion inside a 100 ms window at the end of the caller's budget, which is
      // a coin flip, and a branch that can only be tested by a coin flip is a branch that stays untested:
      // this one silently returned exit 0 for a declared-but-unrun check until it was read out of the
      // source. Nothing in production sets it.
      const verifyFloorMs = Number(process.env.CODEX_DELEGATE_VERIFY_FLOOR_MS ?? 100);
      if (remainingMs < verifyFloorMs) { verifySkipped = "budget-exhausted"; verifyResult = null; }
      else {
      const budgetMs = Math.min(300000, remainingMs);
      // detached: the verifier gets its own process group, and the group is swept right after — Node's
      // own timeout kills only the shell, so anything the verifier backgrounded used to outlive the run.
      const v = spawnSync("/bin/sh", ["-c", opts.verify],
        { cwd, encoding: "utf8", timeout: budgetMs, killSignal: "SIGKILL", maxBuffer: 64 * 1024 * 1024, detached: true });
      if (v.pid) { try { process.kill(-v.pid, "SIGKILL"); } catch {} }
      // "Exited non-zero" and "could not be run at all" are different facts and must not render alike:
      // one means the work is missing, the other means the verifier is broken, and they call for opposite
      // responses. The classification is on the OBSERVED EXIT STATUS, not on whether spawnSync also
      // reported an error:
      //   127 / 126  the shell never ran the command — a typo, or a tool missing from the DRIVER's PATH
      //              (a launchd or hook context routinely lacks pnpm). Says nothing about the work.
      //   no status  never observed an exit at all: killed at the deadline, or spawn itself failed.
      //   status 0   the command DID exit successfully. spawnSync's timeout waits on the stdout pipe as
      //              well as the process, so a verifier that passes while a background process holds the
      //              pipe returns status 0 WITH error ETIMEDOUT — that is a pass we are holding proof of,
      //              and reporting it as unmeasurable throws the proof away.
      const noStatus = v.status === null || v.status === undefined;
      const notRunnable = v.status === 127 || v.status === 126;
      const measured = !noStatus && !notRunnable;
      verifyResult = {
        command: opts.verify, exitCode: v.status, signal: v.signal ?? null,
        ok: measured && v.status === 0, measured,
        error: v.error ? String(v.error.code ?? v.error.message) : null,
        stdout: String(v.stdout ?? "").slice(-2000), stderr: String(v.stderr ?? "").slice(-2000)
      };
      }
    }
  }
  const verifyPassed = verifyResult?.ok === true;
  const verifyFailed = verifyResult != null && !verifyPassed;

  // After the verifier (which runs in the tree), before the report (which carries the outcome).
  const worktree = disposeWorktree(turnStatus === "completed");
  // The receipt is the one artefact no wrapper can fabricate; locate it, READ it, and say what it says,
  // so the coordinator does not have to glob for it and does not have to trust a filename.
  const receipt = findRollout(rootThreadId);
  const receiptPath = receipt?.path ?? null;

  // A refused escalation means the task hit the edge of the sandbox it was given, so the work is very
  // likely incomplete — detectable without reading the prose.
  let code = EXIT.OK;
  if (turnStatus === "timedOut") code = EXIT.TIMEOUT;
  // A parameter the SERVER rejected is the caller's to fix, not something to retry, so it must not land on
  // the same rung as "the turn died". The set of reasoning efforts is per-model and only knowable at
  // runtime — measured: `minimal` is in the server's own generic list and is refused by this account's
  // model, which answered `unsupported_value ... Supported values are: none, low, medium, high, xhigh,
  // max`. As exit 1 that reads as "retry"; as exit 2 it reads as "you passed something this model does not
  // take", and the cause line carries the server's list verbatim.
  else if (turnStatus !== "completed" && invalidRequest(turnError)) code = EXIT.USAGE;
  else if (turnStatus !== "completed") code = EXIT.TURN_NOT_COMPLETED;
  // An unattended interaction the driver could not answer means the turn proceeded without something it
  // asked for. That is never a success, and it is not an escalation either — no sandbox change fixes it.
  else if (interactions.length) code = EXIT.INTERACTION;
  // Escalations before NO_COMMANDS: a refused approval explains the missing command, and reporting
  // "nothing ran" would hide the reason.
  else if (escalations.length) code = EXIT.ESCALATED;
  // Above the proxies below it: this one measured the end state directly instead of inferring it.
  // "The check said no" and "the check could not be run" are different instructions to the caller — redo
  // the work, versus fix the verifier — so they get different codes. Reporting the second as 9 told the
  // caller to discard work the run never measured, while the text beside it said the opposite.
  // A verifier the deadline left no room for is the same fact as one that could not be executed: it was
  // DECLARED and it was not measured. It used to leave verifyResult null, which both verify rungs test
  // for, so the ladder fell through to the weaker gates and a run with an unrun check could reach 0 —
  // the exact "report says success, the work is unverified" shape --verify exists to prevent.
  else if (verifySkipped === "budget-exhausted") code = EXIT.VERIFY_UNMEASURABLE;
  else if (verifyResult && !verifyResult.measured) code = EXIT.VERIFY_UNMEASURABLE;
  else if (verifyFailed) code = EXIT.VERIFY_FAILED;
  // --allow-no-commands waives the "at least one command" floor. It must NOT waive an expectation the
  // caller declared: asking for proof and then accepting its absence is the exact failure this gate exists
  // to prevent. A passing --verify does not waive it either — the end state can be right while the work
  // drifted, e.g. a stale dist/ satisfying `test -f dist/index.js` for a build that never ran.
  else if (expected.length === 0 && (opts.expectRe || !opts.allowNoCommands)) code = EXIT.NO_COMMANDS;
  else if (!answer) code = EXIT.NO_ANSWER;
  // The caller asked for a shape and spent a corrective turn not getting it. Above COMMAND_FAILED:
  // an unusable answer is the more actionable complaint, and 11 is still visible in the report.
  else if (opts.outputSchema && schemaErrs.length) code = EXIT.SCHEMA;
  // A command that ran and failed is a failure of the work, whatever the answer claims — one incidental
  // success (a skill-file read) must not mask it. A PASSING --verify overrules it, because iterative work
  // normally contains failed commands: the first test run fails, the model fixes it, the second passes.
  // The waiver is on the check's RESULT; keying it on the flag's presence let a check that never executed
  // wave a real failure through.
  // Under --review the deliverable is the review, and the reviewer's own failed probes are its working
  // method, not a failure of the work — measured live: a real review ran 26 commands, several of them
  // failing greps, and exited 11 with a perfectly good review in hand. The counts stay in the report.
  else if ((failedCmds.length || failedPatches.length) && !verifyPassed && !opts.review) code = EXIT.COMMAND_FAILED;

  const report = {
    ok: code === EXIT.OK, exitCode: code, level: opts.level, sandbox: effectiveSandbox, cwd,
    // Named for what it is. As `writableRoots` beside a `sandbox` object that also has `writableRoots`, it
    // read as the grant, so a report showing `[]` while the server had widened the sandbox was one glance
    // from being believed. The grant is `sandbox.writableRoots`; assertWriteSandbox now refuses any
    // difference between them, but the field should not have needed that to be unambiguous.
    writableRootsRequested: roots, network: Boolean(opts.network),
    // Which Codex installation answered. Two runs that differ only in this can differ in everything else,
    // so a report that omits it cannot be compared with another.
    codexHome,
    // What was REQUESTED; null means the thread inherited config.toml. reasoningEffort below is what the
    // server actually selected, which is the one worth reading back.
    effort: opts.effort ?? null, reasoningEffort: selectedEffort,
    model: selectedModel, turnStatus, turnError, threadId: rootThreadId,
    // What the seat cost, straight from the server's own accounting; null when no usage event arrived.
    tokenUsage,
    ...(opts.outputSchema ? { outputAttempts, outputSchemaOk: schemaErrs.length === 0,
        schemaErrors: schemaErrs.length ? schemaErrs.slice(0, 12) : null,
        // What the driver's shallow validator could NOT re-verify; the server still enforced these
        // during generation. Null means the whole schema was within the checked subset.
        schemaKeywordsUnchecked: opts.schemaUnchecked } : {}),
    commandsSucceeded: ran.length, commandsMatchingExpectation: expected.length,
    commandsFailed: failedCmds.length, commandsBlocked: blocked.length,
    // Probes that answered "no" (a no-match grep, a false test) — not failures, not successes.
    commandsProbeNegative: probeNegatives.length,
    // For a rename the file that EXISTS afterwards is the destination; report that, not the source.
    filesTouched: fileChanges.filter((f) => f.status === "completed").map((f) => f.move ?? f.path),
    fileChangesFailed: failedPatches,
    escalations, interactions, unparsedLines, expectCommand: opts.expect ?? null,
    // Transient provider failures the driver absorbed with a bounded backoff; empty on the vast
    // majority of runs, and the honest record of the delay when it happened.
    transientRetries,
    // What the turn did beyond commands and files: the model's own summaries of its reasoning
    // (bounded), item types the gates ignore, and the subagent threads the server ran under ours —
    // visible activity, never evidence.
    reasoningSummary: reasoningSummaries.length ? reasoningSummaries.join("\n---\n").slice(0, 8000) : null,
    otherItemCounts: Object.keys(otherItemCounts).length ? otherItemCounts : null,
    subagentThreads: [...subagentThreads.entries()].map(([threadId, t]) => ({ threadId, ...t })),
    // What a seat FILE declared, in order, when one was used. A wrapped seat is otherwise indistinguishable
    // from a hand-typed one in the report, and the fields a relay wrote are exactly what a coordinator
    // needs to see when it did not write them itself.
    ...(seatFileFields ? { seatFileFields } : {}),
    // null only when no --expect-command was given, so a caller can tell "not asked" from "asked and missed".
    expectationOk: opts.expectRe ? expected.length > 0 : null,
    // The rollout receipt, located and verified rather than merely implied. receiptOk false is "no
    // rollout in the last two days of ~/.codex/sessions whose opening session_meta record names this
    // thread", which a nonstandard layout can also produce — read the comment on findRollout before
    // treating it as proof of fabrication. receiptWhy says which of the two it was.
    receiptPath, receiptOk: receipt?.verified === true, receiptWhy: receipt?.why ?? (receiptPath ? null : "no rollout naming this thread in the last two days"),
    // Straight out of the verified record. A wrapper that forwarded the work has no thread whose
    // session_meta says this, and a coordinator auditing a seat reads these rather than a path.
    receiptOriginator: receipt?.originator ?? null, receiptModelProvider: receipt?.modelProvider ?? null,
    receiptCwd: receipt?.cwd ?? null,
    ...(worktree ?? {}),
    // A completed turn that ran nothing exits 5; when no expectation was declared, the one legitimate
    // shape of that run (a recall-only follow-up) has a flag, and the report should name it.
    ...(code === EXIT.NO_COMMANDS && !opts.expectRe
      ? { hint: "if running nothing was the point, re-run with --allow-no-commands" } : {}),
    verify: verifyResult, verifySkipped,
    answerPhase: final?.phase ?? null, commentaryOnly,
    // Always on disk, so `answer` can be capped without losing anything: the coordinator reads the head and
    // opens the file only when the head is not enough. This is the shape a Claude subagent already has —
    // a short return plus a transcript — and the seat had no equivalent.
    answer, answerPath, answerTruncated: answer !== fullAnswer,
    // Only present when --answer-json asked for it, so a caller can tell "did not ask" from "asked and the
    // model answered in prose anyway". Absent rather than null in the ordinary case, because a null here
    // would read as a failed parse.
    // The FULL answer, never the clipped one. --brief cuts at 20 lines, so a 30-line JSON object parsed as
    // truncated garbage and came back as answerJson: null with a syntax error — the exact signature the
    // docs give for "asked for JSON and the model answered in prose". Two flags that are each fine alone
    // silently destroyed the other's output.
    ...(opts.answerJson ? parseAnswerJson(fullAnswer) : {})
  };

  let out;
  if (opts.json) {
    out = `${JSON.stringify({ ...report, commands }, null, 2)}\n`;
  } else {
    const L = [answer, ""];
    L.push(`--- verification -----------------------------------------`);
    L.push(`level=${opts.level} sandbox=${effectiveSandbox?.type ?? sandbox} turn=${turnStatus} answerPhase=${final?.phase ?? "none"}`);
    // Only the surprising case is worth a line: on the host home the caller's plugins and skills were in
    // the turn, so this run is not comparable with an isolated one.
    if (codexHome === null) L.push("home=host — the caller's plugins and skills were loaded into this turn");
    if (!opts.ephemeral) L.push(`threadId=${rootThreadId}  (continue with --resume ${rootThreadId})`);
    if (rootThreadId) L.push(receipt?.verified
      ? `receipt: ${receiptPath}  (originator=${receipt.originator ?? "?"} provider=${receipt.modelProvider ?? "?"})`
      : receiptPath ? `receipt: FOUND BUT UNVERIFIED at ${receiptPath} — ${receipt.why}`
      : `receipt: NOT FOUND in the last two days of ~/.codex/sessions — verify the seat by other means`);
    if (tokenUsage?.total) L.push(`tokens: in=${tokenUsage.total.inputTokens ?? "?"} (cached ${tokenUsage.total.cachedInputTokens ?? 0}) out=${tokenUsage.total.outputTokens ?? "?"} total=${tokenUsage.total.totalTokens ?? "?"}`);
    if (opts.outputSchema) L.push((schemaErrs.length
      ? `output-schema: FAILED after ${outputAttempts} attempt(s) — ${schemaErrs.slice(0, 3).join("; ")}`
      : `output-schema: matched (${outputAttempts} attempt(s))`)
      + (opts.schemaUnchecked ? ` [unchecked keywords: ${opts.schemaUnchecked.join(", ")}]` : ""));
    if (worktree) {
      L.push(worktree.worktreeRemoved
        ? `worktree: removed (${worktree.worktreeHarvested ? "work harvested" : "clean"}) — ${worktree.worktreeFleet ?? 0} codex worktree(s) remain under this repo`
        : `worktree: PRESERVED at ${worktree.worktreePath} — ${worktree.worktreePreserved}`);
      if (worktree.worktreeDiffStat) L.push(`  ${worktree.worktreeDiffStat.split("\n").at(-1)}`);
      if (worktree.worktreeDiffPath) L.push(`  tracked diff saved to ${worktree.worktreeDiffPath}`);
      if (worktree.worktreeUntrackedPath) L.push(`  untracked files saved to ${worktree.worktreeUntrackedPath}`);
      if (!worktree.worktreeRemoved) {
        L.push(`  harvest, then: ${worktree.worktreeRemoveCommand}`);
        if ((worktree.worktreeFleet ?? 0) > 1) L.push(`  fleet: ${worktree.worktreeFleet} codex worktrees under this repo`);
      }
    }
    L.push(`commands: ${ran.length} succeeded` +
      `${failedCmds.length ? `, ${failedCmds.length} FAILED` : ""}` +
      `${probeNegatives.length ? `, ${probeNegatives.length} probe(s) answered no` : ""}` +
      `${blocked.length ? `, ${blocked.length} never ran` : ""}`);
    for (const c of ran.slice(-8)) L.push(`  exit=${c.exitCode} ${c.command.slice(0, 90)}`);
    for (const c of failedCmds) L.push(`  FAILED exit=${c.exitCode} ${c.command.slice(0, 90)}`);
    for (const c of blocked) L.push(`  NEVER RAN  ${c.command.slice(0, 90)}`);
    const wrote = fileChanges.filter((f) => f.status === "completed");
    if (wrote.length) {
      L.push(`files: ${wrote.length} written`);
      for (const f of wrote.slice(-12)) L.push(f.move ? `  rename ${f.path} -> ${f.move}` : `  ${f.kind} ${f.path}`);
    }
    for (const f of failedPatches) L.push(`  PATCH ${String(f.status).toUpperCase()} ${f.path}`);
    if (Object.keys(otherItemCounts).length)
      L.push(`other activity: ${Object.entries(otherItemCounts).map(([k, v]) => `${k} x${v}`).join(", ")}`);
    if (subagentThreads.size)
      L.push(`subagent threads: ${[...subagentThreads.entries()].map(([id, t]) => `${id} (${t.items} item(s), ${t.commands} command(s))`).join("; ")}`);
    if (escalations.length) {
      L.push(`escalations refused: ${escalations.length} — the sandbox was too small for this task.`);
      for (const e of escalations) L.push(`  ${e.method} ${e.detail}`);
      L.push(`  widen it with --writable <dir> or --network rather than approving per command.`);
    }
    // Both checks always report their verdict. Printing only the exit code made a run whose end state was
    // proven good and one whose end state was proven broken produce byte-identical reports.
    if (verifyResult) {
      // "could not be measured" is not "the work is not there" — a verifier that overran maxBuffer or the
      // deadline says nothing about the work, and printing it as FAIL makes the caller discard good work.
      L.push(verifyResult.measured
        ? `verify: \`${verifyResult.command}\` -> ${verifyResult.ok ? "PASS" : "FAIL"} (exit ${verifyResult.exitCode})` +
          (verifyResult.error ? ` [${verifyResult.error} while draining, exit status observed anyway]` : "")
        : `verify: \`${verifyResult.command}\` COULD NOT BE MEASURED (` +
          (verifyResult.exitCode === 127 ? "command not found on the driver's PATH"
            : verifyResult.exitCode === 126 ? "found but not executable"
            : verifyResult.error ?? "no exit status") +
          `${verifyResult.signal ? `, killed by ${verifyResult.signal}` : ""}) — this says nothing about the work; fix the verifier.`);
    } else if (opts.verify) {
      L.push(`verify: \`${opts.verify}\` NOT RUN (${verifySkipped}) — the end state is unmeasured.`);
    }
    if (opts.expectRe) {
      L.push(expected.length
        ? `expect-command /${opts.expect}/: ${expected.length} successful command(s) matched`
        : `expect-command /${opts.expect}/: NO successful command matched — the turn may have drifted`);
    }
    if (unparsedLines) L.push(`${unparsedLines} unparsable line(s) from the server — the pinned schema may be behind \`codex --version\`.`);
    if (interactions.length) L.push(`UNANSWERABLE server requests — no sandbox change fixes these: ${interactions.join(", ")}`);
    if (turnStatus !== "completed") {
      L.push(`TURN ${String(turnStatus).toUpperCase()} — the answer above is incomplete.`);
      if (turnStatus === "timedOut") L.push("  a timeout is the case most likely to leave a half-written tree; inspect the cwd before reusing it.");
      if (turnError) L.push(`  cause: ${errKind(turnError)} — ${errText(turnError)}`);
      if (stderrBuf.trim()) L.push(`  stderr: ${stderrBuf.trim().split("\n").slice(-3).join(" | ")}` +
        (stderrDropped ? `  [+${stderrDropped} earlier bytes dropped]` : ""));
    }
    // Three different facts used to share one line: exit 5 proper, a waived no-command turn, and
    // commands that all failed. Each now says what actually happened, and exit 5 names its waiver.
    else if (code === EXIT.NO_COMMANDS) L.push(`NO COMMAND ${commands.length ? "SUCCEEDED" : "EXECUTED"}: the answer is unverified prose.` +
      (opts.expectRe ? "" : " If running nothing was the point, re-run with --allow-no-commands."));
    else if (ran.length === 0) L.push(commands.length
      ? `NOT TRUSTWORTHY: commands ran but none succeeded; the answer is unverified.`
      : `no command executed — waived by --allow-no-commands.`);
    L.push(`Note: a passing gate proves commands ran, not that the right ones did. Check the list.`);
    out = `${L.join("\n")}\n`;
  }
  writeJob({ exitCode: code, turnStatus, answerPath, endedAt: new Date().toISOString() });
  process.exitCode = code;
  // Exit only once stdout has actually drained. A large report on a pipe is chunked, and exiting on the
  // next tick truncates it at the pipe buffer — measured at 262144 bytes for a 20MB report.
  // process.exit waits for shutdown() now: exiting on the same tick used to discard the SIGKILL
  // escalation timer, which is how a TERM-ignoring test server outlived every normal completion.
  flushing = true;
  process.stdout.write(out, () => { flushing = false; shutdown().then(() => process.exit(code)); });
  // If stdout never drains, the report did not reach the caller — that is a transport failure, not
  // the success the run would otherwise have been.
  setTimeout(() => {
    process.stderr.write("codex-delegate: stdout did not drain; report may be truncated\n");
    shutdown().then(() => process.exit(EXIT.TRANSPORT));
  }, 5000).unref?.();
}

// ---------------------------------------------------------------- run

async function main() {
  await setup();
  // Once a child exists, a timeout hands back the partial result rather than discarding it; before that
  // there is nothing to report, so abort() also has to unblock a stdin read that may never end.
  const deadline = setTimeout(() => {
    if (child && rootThreadId) { interruptTurn(); finish("timedOut"); }
    else abort(EXIT.TIMEOUT, `timed out after ${opts.timeout}s`);
    // Anchored on the process start, not on this line: the config probe runs before this timer is
    // armed, and a relative deadline overshot the caller's wall clock by however long it took.
  }, Math.max(50, startedAtMs + opts.timeout * 1000 - Date.now()));
  deadline.unref?.();

  let prompt = opts.prompt;
  if (prompt === undefined && !opts.review) {
    if (process.stdin.isTTY) fail(EXIT.USAGE, "no prompt: pass --prompt or pipe one on stdin");
    process.stdin.setEncoding("utf8");   // raw Buffers split multi-byte chars at chunk boundaries
    let s = "";
    for await (const c of process.stdin) {
      s += c;
      if (Buffer.byteLength(s) > MAX_PROMPT_BYTES) fail(EXIT.USAGE, `prompt exceeds ${MAX_PROMPT_BYTES} bytes`);
    }
    prompt = s;
  }
  if (settled) throw new Bail();   // aborted while reading stdin; the exit code is already set
  if (!opts.review) {
    prompt = prompt.trim();
    if (!prompt) fail(EXIT.USAGE, "empty prompt");
  }

  child = spawn(codexBin, spawnArgs, {
    cwd, stdio: ["pipe", "pipe", "pipe"], detached: true,
    env: codexHome === null ? process.env : { ...process.env, CODEX_HOME: codexHome },
  });
  child.stderr.setEncoding("utf8");
  // Bounded: a run may legitimately last two hours, and abort() prints this whole buffer. Keep the TAIL,
  // because the last words before a crash are the useful ones, and say how much was dropped.
  child.stderr.on("data", (c) => {
    stderrBuf += c;
    if (stderrBuf.length > STDERR_KEEP) {
      stderrDropped += stderrBuf.length - STDERR_KEEP;
      stderrBuf = stderrBuf.slice(-STDERR_KEEP);
    }
  });
  child.on("error", (e) => { rejectAllPending(e); abort(EXIT.TRANSPORT, `cannot start codex: ${e.message}`); });
  child.on("exit", (code, signal) => {
    const e = new Error(`codex app-server exited (${signal ? `signal ${signal}` : `code ${code}`})`);
    rejectAllPending(e);
    if (!settled) abort(EXIT.TRANSPORT, e.message);
  });
  child.stdin.on("error", () => {});

  readline.createInterface({ input: child.stdout }).on("line", (line) => {
    let msg;
    try { msg = JSON.parse(line); } catch { unparsedLines++; return; }   // readline already reassembles split lines
    try { handleMessage(msg); } catch (e) { abort(EXIT.TRANSPORT, `protocol handling failed: ${e.message}`); }
  });

  let nextId = 1;
  const request = (method, params) => {
    const id = nextId++;
    child.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", id, method, params })}\n`);
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject, method }));
  };
  requestFn = request;

  await request("initialize", {
    clientInfo: { title: "codex-delegate", name: "Claude Code", version: "2.0" },
    capabilities: {
      experimentalApi: false, requestAttestation: false,
      // Every one of these is parsed and dropped: the driver reads item/completed and turn/completed and
      // nothing else. Left empty, a `pnpm test` streams its whole output through the pipe line by line for
      // no reader. The list is taken from ServerNotification in the pinned schema rather than guessed —
      // the command-output streams are the large ones, and are exactly what a test-running delegation
      // produces most of.
      optOutNotificationMethods: [
        "item/agentMessage/delta",
        "item/reasoning/summaryTextDelta", "item/reasoning/summaryPartAdded", "item/reasoning/textDelta",
        "item/commandExecution/outputDelta", "command/exec/outputDelta", "process/outputDelta",
        "item/fileChange/outputDelta", "item/plan/delta"
      ]
    }
  });
  child.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", method: "initialized", params: {} })}\n`);

  // Standing rules belong on the thread, not in the task prompt: they then govern every turn of a
  // resumed thread and do not compete with the task text for attention. `codex exec` cannot do this.
  const developerInstructions = [
    "You are being driven by a Claude Code coordinator, unattended. Nobody will answer a question.",
    opts.webSearch
      ? "Prefer the local shell and filesystem; use web search only for what is not in this checkout, and cite the source."
      : "Use the local shell and filesystem only. Do not use web search; cite files you actually read.",
    "If a command cannot run, reply with the single token COMMAND_BLOCKED for that step and continue.",
    "Never report a test as passing unless you ran it and saw the count in this turn.",
    "State uncertainty plainly rather than guessing; an honest 'I could not determine this' is useful.",
    // The coordinator machine-reads this answer. Saying so is what makes the JSON arrive bare; without it
    // the model reaches for a fenced block, and a fence is not JSON.
    ...(opts.answerJson
      ? ["Your final answer must be ONE JSON object and nothing else: no prose before or after, no markdown code fence."]
      : []),
    // Parity with a Claude subagent, whose final text is a summary while the detail stays in a transcript
    // the coordinator opens only if it needs to. Without this a Codex seat hands back its whole working
    // note — one returned 13 KB of prose straight into the coordinator's context.
    ...(opts.brief
      ? [`Answer in at most ${BRIEF_LINES} lines: the conclusion, then only what changes what the reader does next.`,
         "Put anything longer — diffs, transcripts, tables, evidence — in a file under $TMPDIR and give its absolute path."]
      : [])
  ].join(" ");

  // Sending `sandbox` at all suppresses the permission profile — the server reports
  // activePermissionProfile: null and the $TMPDIR grant silently disappears. So at --level read the
  // parameter is omitted and the profile is pinned via -c instead; the response is then asserted below,
  // because an unapplied profile must never pass as if it had applied.
  const sandboxParam = sandbox === null ? {} : { sandbox };
  const resuming = Boolean(opts.resume);
  // WHO may approve is as load-bearing as what the sandbox permits, and it is a separate axis. With
  // approvalsReviewer "auto_review" the server hands approvals to its own subagent, so they never reach
  // this driver: escalations stay empty, the refusal policy is silently disarmed, and a sandbox escape can
  // be granted while the run exits 0. Measured: the sandbox object is byte-identical under "user" and
  // "auto_review", so no amount of checking type/roots/network can tell them apart. `approvals_reviewer`
  // is a real config key and a menu item in the interactive TUI, so this is one toggle away by accident.
  const approvalsReviewer = "user";
  const threadReq = resuming
    ? ["thread/resume", { threadId: opts.resume, cwd, model: opts.model ?? null, approvalPolicy: "on-request", approvalsReviewer, ...sandboxParam, developerInstructions }]
    // Resumable by default. Whether a thread is worth continuing is only knowable after reading the
    // answer, and an ephemeral thread cannot be continued — so opting IN was a trap: you learned you
    // needed the flag exactly when it was too late to pass it.
    : ["thread/start", { cwd, model: opts.model ?? null, approvalPolicy: "on-request", approvalsReviewer, ...sandboxParam, developerInstructions,
        serviceName: "claude-code-codex-delegate", ephemeral: Boolean(opts.ephemeral) }];
  const thread = await request(threadReq[0], threadReq[1]);
  // Asked for above, asserted here, at BOTH levels — write level's writable-root boundary is escapable the
  // same way. The field is `required` on the response in the pinned schema, so a server that stops sending
  // it yields undefined and refuses: fail-closed by construction rather than by convention.
  // The approval POLICY is asserted for the same reason as the reviewer, and it is the reason this driver
  // uses app-server at all: where an MDM profile restricts the allowed policies, a policy it does not
  // permit is silently CLAMPED to another one, after which every command is denied while the run still
  // looks healthy. That is the failure the whole skill exists to route around — so if the server did not
  // echo the policy we asked for, stop rather than discover it one refused command at a time.
  if (thread.approvalPolicy !== "on-request")
    fail(EXIT.TRANSPORT, `the server applied approvalPolicy ${JSON.stringify(thread.approvalPolicy ?? null)}, not "on-request"; ` +
      `a clamped policy denies every command while the run still exits cleanly. Refusing to continue.`);
  if (thread.approvalsReviewer !== approvalsReviewer)
    fail(EXIT.TRANSPORT, `approvals are routed to ${JSON.stringify(thread.approvalsReviewer ?? null)}, not to this driver; ` +
      `it could approve a sandbox escape without the run ever reporting an escalation. Refusing to continue.`);
  // A resumed thread with a turn still running would hand us that turn's id from turn/start, and its
  // old events would satisfy this invocation while the new prompt was never consumed.
  effectiveSandbox = thread.sandbox ?? null;
  assertSandbox(thread);

  const st = thread.thread?.status?.type ?? null;
  if (resuming && st === "active") fail(EXIT.BUSY, `thread ${opts.resume} still has a turn running; wait for it to finish`);
  if (resuming && st && st !== "idle") fail(EXIT.TRANSPORT, `thread ${opts.resume} is ${st} and cannot be resumed`);

  // Announced BEFORE the turn, not in the report: a delegation runs for minutes, and the thread id is
  // the key to tailing its live rollout under ~/.codex/sessions — a coordinator watching a long seat
  // should not have to wait for the end to learn which run it is.
  process.stderr.write(`codex-delegate: threadId=${rootThreadId} (live rollout: ~/.codex/sessions/YYYY/MM/DD/rollout-*-${rootThreadId}.jsonl)\n`);
  writeJob({ threadId: rootThreadId, pid: process.pid, cwd, level: opts.level, started: new Date().toISOString() });

  if (opts.review) {
    // The server's own reviewer, on this thread. No lastTurnParams: a transient retry cannot replay a
    // review (the guard on the retry checks for exactly this).
    await request("review/start", { threadId: rootThreadId, target: opts.reviewTarget, delivery: "inline" });
    return;
  }

  if (opts.outputSchema) outputAttempts = 1;   // attempts count turns STARTED, this being the first
  lastTurnParams = {
    threadId: rootThreadId,
    input: [{ type: "text", text: prompt, text_elements: [] }, ...(opts.attachments ?? [])],
    model: opts.model ?? null, effort: null,
    ...(opts.outputSchema ? { outputSchema: opts.outputSchema } : {})
  };
  await request("turn/start", lastTurnParams);
}

// Installing a handler removes Node's default terminate-on-signal, so the handler must always end the
// process. Without the settled branch a run that has already reported ignores every signal it handles,
// and only SIGKILL reclaims it.
//
// SIGHUP is in the list, and its absence was a hole rather than an omission: it is what a closing
// terminal and a dying parent shell send, which is the ordinary end of a backgrounded delegation.
// Measured without it — driver exit 129, a TERM-ignoring descendant reparented to pid 1, the cwd lock
// left behind, and a zero-byte report: every guarantee this driver makes about teardown, lost to the
// one signal nobody sends on purpose.
for (const sig of ["SIGINT", "SIGTERM", "SIGHUP"]) {
  process.on(sig, () => {
    // A repeat signal while teardown is already running escalates the group straight to SIGKILL. The
    // old path called process.exit() here, which discarded the pending escalation — the second Ctrl-C
    // was precisely how a TERM-ignoring descendant got left behind.
    if (shutdownDone) { killGroup("SIGKILL"); return; }
    if (settled) {
      if (flushing) return;   // the report is mid-write; let it finish or hit its own timer
      shutdown().then(() => process.exit(process.exitCode ?? EXIT.TRANSPORT));
      return;
    }
    // A turn that has already produced evidence is REPORTED, not discarded. abort() writes no report at
    // all, so a cancelled delegation used to hand back zero bytes of stdout while its commands, files
    // and answer sat in memory — measured: six seats stopped mid-run, six empty reports, the whole
    // product of each thrown away. This is the same choice --timeout already makes one line below in
    // main(), and it lands on the published rung for "the turn did not complete" (exit 1) rather than
    // on transport (4), which means "codex crashed or the rights were wrong" and did not happen here.
    // Before a thread exists there is nothing to report, and 4 stays.
    process.stderr.write(`codex-delegate: interrupted by ${sig}\n`);
    if (child && rootThreadId) { interruptTurn(); finish("interrupted"); return; }
    abort(EXIT.TRANSPORT, `interrupted by ${sig} before the thread existed`);
    shutdown().then(() => process.exit(EXIT.TRANSPORT));
  });
}

// The synchronous last resort for exits that bypassed shutdown() — a crash, a code path that called
// process.exit directly. After a clean teardown every one of these is a no-op.
process.on("exit", () => {
  if (child) killGroup("SIGKILL");
  if (probeChild) { try { process.kill(-probeChild.pid, "SIGKILL"); } catch {} }
  releaseLock();
  worktreeLastResort();
});

main().catch((e) => {
  if (e instanceof Bail) { shutdown(); return; }
  abort(EXIT.TRANSPORT, e.message);
});
